return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Urdu','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-06 22:37+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'ur','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" محفوظ کیا گیا۔','"%1$s" created. %2$d template updated.'=>'"%1$s" تخلیق کیا گیا۔ %2$d سانچے اپ ڈیٹ کیے گئے۔' . "\0" . '"%1$s" تخلیق کیا گیا۔ %2$d سانچے اپ ڈیٹ کیے گئے۔','"%s" created.'=>'"%s" تخلیق کیا گیا۔','"product" (replaces "article")'=>'مصنوعہ (مضمون کی جگہ)','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d حروف — اچھا، مثالی حد سے کچھ زیادہ %2$d لیکن قابل قبول %3$d-حرف کی حد کے اندر۔ %4$s','%1$d chars — ideal length. %2$s'=>'%1$d حروف — مثالی لمبائی۔ %2$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d حروف — ممکنہ طور پر SERPs میں کٹ گئے ہیں (%2$d سے کم رکھیں)۔ %3$s','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d حروف — بہت مختصر ہے (مقصد %2$d–%3$d ہے)۔ %4$s','%1$d internal, %2$d external.'=>'%1$d داخلی، %2$d خارجی۔','%1$d of %2$d image(s) missing alt text.'=>'%1$d میں سے %2$d تصویر سے متبادل متن غائب ہے۔','%1$d words — below recommended minimum of %2$d.'=>'%1$d الفاظ — سفارش کردہ کم سے کم %2$d سے کم۔','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d الفاظ — بہت پتلا مواد۔ کم از کم %2$d الفاظ تک بڑھانے پر غور کریں۔','%d chars — good length.'=>'%d حروف — اچھی لمبائی۔','%d external link(s), no internal links.'=>'%d خارجی لنک(ز)، کوئی داخلی لنک نہیں۔','%d external link(s), no internal links. Add internal links to related content.'=>'%d خارجی روابط، کوئی داخلی روابط نہیں۔ متعلقہ مواد کے لیے داخلی روابط شامل کریں۔','%d H1 tags found — a page should have exactly one H1.'=>'%d H1 ٹیگز ملے — ایک صفحہ میں بالکل ایک H1 ہونا چاہیے۔','%d image(s), all have alt text.'=>'%d تصویر، سب کے پاس متبادل متن ہے۔','%d language not yet linked'=>'%d زبان ابھی تک منسلک نہیں ہے' . "\0" . '%d زبانیں ابھی تک منسلک نہیں ہیں','%d link updated.'=>'%d لنک اپ ڈیٹ کیا گیا۔' . "\0" . '%d لنکس اپ ڈیٹ کیے گئے۔','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'%d لوکل فائل خودکار طریقے سے حذف نہیں کی جا سکی (DISALLOW_FILE_MODS سیٹ ہے)۔ اسے دستی طور پر اپنے سرور یا WP-CLI کے ذریعے حذف کریں: wp language core uninstall <locale>' . "\0" . '%d لوکل فائلیں خودکار طریقے سے حذف نہیں کی جا سکیں (DISALLOW_FILE_MODS سیٹ ہے)۔ انہیں دستی طور پر اپنے سرور یا WP-CLI کے ذریعے حذف کریں: wp language core uninstall <locale>','%d locale file removed.'=>'%d لوکل فائل حذف کی گئی۔' . "\0" . '%d لوکل فائلیں حذف کی گئی۔','%d locale pack installed.'=>'%d لوکیل پیک انسٹال ہے۔' . "\0" . '%d لوکیل پیک انسٹال ہیں۔','%d navigation reference updated.'=>'%d نیویگیشن حوالہ اپ ڈیٹ کیا گیا۔' . "\0" . '%d نیویگیشن حوالہ جات اپ ڈیٹ کیے گئے۔','%d part reference updated.'=>'%d حصے کا حوالہ اپ ڈیٹ کیا گیا۔' . "\0" . '%d حصوں کے حوالے اپ ڈیٹ کیے گئے۔','%d words.'=>'%d الفاظ۔','%s Archive'=>'%s آرکائیو','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s فعال ہے اور پہلے ہی Schema.org JSON-LD پیدا کرتا ہے۔ Lingua Forge نے اس کے اپنے schema آؤٹ پٹ کو غیر فعال کر دیا ہے تاکہ متصادم گراف سے بچا جا سکے۔ Open Graph کے برعکس — جہاں LF دوسرے پلگ ان کے آؤٹ پٹ پر og:locale شامل کرتا ہے — schema کو صاف طریقے سے شامل نہیں کیا جا سکتا: نقل یا اوورلیپنگ JSON-LD گراف تصدیقی غلطیاں پیدا کرتے ہیں۔ اگر آپ چاہتے ہیں کہ LF ساختہ ڈیٹا سنبھالے تو معلوم شدہ پلگ ان میں schema آؤٹ پٹ کو غیر فعال کریں۔','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s فعال ہے اور اپنی سائیٹ میپ تیار کرتا ہے۔ وہ سائیٹ میپ LF سے الگ ہے۔ دونوں کو Google Search Console میں جمع کروانا چاہیے: SEO پلگ ان کا سائیٹ میپ آپ کے مواد کی فہرست بناتا ہے؛ LF کا سائیٹ میپ کثیر لسانی متبادل روابط شامل کرتا ہے۔ LF کا سائیٹ میپ خودکار طور پر robots.txt میں اعلان کیا جاتا ہے۔','(avg %.1f hits/block)'=>'(اوسط %.1f ہٹس/بلاک)','(avg %.1f hits/entry)'=>'(اوسط %.1f ہٹس/داخلہ)','(disabled)'=>'(غیر فعال)','(no title) #%d'=>'(کوئی عنوان نہیں) #%d','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} میں کوئی قابلِ تبدیل لنک نہیں تھا — مزید جانچ کے لیے دوبارہ اسکین کریں)','.txt file(s) in the directory'=>'.txt فائل(یں) ڈائریکٹری میں','/ 100'=>'/ 100','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — کوئی H2 ذیلی سرخیاں نہیں (اس قسم کے مواد کے لیے قابل قبول)۔','1 H1 ✓ — no H2 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — کوئی H2 ذیلی عنوان نہیں ملا۔ H2 شامل کرنے سے ساخت بہتر ہوتی ہے۔','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓، %1$d H2، %2$d H3۔','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d مقامی ٹیمپلیٹ(یں) &#8220;%2$s&#8221; تھیم سے محفوظ ہیں لیکن فی الحال غیر فعال ہیں۔ اگر آپ اس تھیم کو دوبارہ فعال کریں گے تو یہ دوبارہ فعال ہو جائیں گے۔ اپنی ترجمہ کو نئے تھیم میں منتقل کرنے کے لیے، انہیں دوبارہ پیدا کریں <strong>سیٹنگز → Lingua Forge → Router → FSE scaffold</strong> کے ذریعے۔','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> خودکار فکس کے قابل لنک','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> لنک جن کا دستی جائزہ لینا ہے','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> پرانی راہ/راہیں','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> ٹیمپلیٹ مسئلہ/مسائل','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'سائٹ کے روٹ پر ایک جسمانی robots.txt فائل موجود ہے۔ WordPress کا ورچوئل robots.txt — اور LF کا Sitemap: فلٹر — بائی پاس کیا گیا ہے۔ LF کا سائیٹ میپ سرچ انجنز کو اعلان نہیں کیا گیا۔','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'صرف مرتب شدہ .mo فائلیں قبول کی جاتی ہیں۔ فائل کا نام {textdomain}-{locale}.mo کے پیٹرن کی پیروی کرنا چاہیے۔ ایک ہی نام کی فائل اپ لوڈ کرنے سے وہ تبدیل ہو جائے گی۔','Action'=>'عمل','Actions'=>'عمل','active'=>'فعال','Active Languages'=>'فعال زبانیں','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'فعال زبانیں: ہر زبان کو شامل کریں جسے آپ سپورٹ کرنا چاہتے ہیں۔ ہر زبان کو ایک URL پیش لفظ یا سب ڈومین اور ایک hreflang ٹیگ ملتا ہے جو صفحہ کے &lt;head&gt; میں ہوتا ہے۔','Active Provider'=>'فعال فراہم کنندہ','Add entry'=>'داخلہ شامل کریں','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'خاکہ کو بہتر بنانے کے لیے ہدایات شامل کریں — مثلاً اسے مختصر کریں، نتیجہ شامل کریں، زیادہ رسمی انداز استعمال کریں، FAQ بلاک شامل کریں…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'مسودہ بہتر بنانے کے لیے ہدایات شامل کریں — مثلاً، اسے مختصر کریں، نتیجہ کا ایک اختتامی حصہ شامل کریں، زیادہ رسمی انداز استعمال کریں…','Add new entry'=>'نیا داخلہ شامل کریں','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'ایک لائن میں ایک اصطلاح شامل کریں۔ ماخذ اصطلاح اور ہدف کی نمائندگی دونوں ضروری ہیں۔ زبان کا جوڑا تعین کرتا ہے کہ کون سے ترجمہ کے کام اس پابندی پر لاگو ہوتے ہیں۔','Add Sitemap directive to robots.txt'=>'robots.txt میں Sitemap ہدایت شامل کریں','Add the following line to your robots.txt manually:'=>'اپنے robots.txt میں مندرجہ ذیل لائن دستی طور پر شامل کریں:','Add WooCommerce product tags to Open Graph output'=>'Open Graph آؤٹ پٹ میں WooCommerce مصنوعات کے ٹیگز شامل کریں','Adds a link to the home page so visitors can browse in their language.'=>'ایک لنک شامل کرتا ہے تاکہ زائرین اپنی زبان میں براؤز کر سکیں۔','Administrators only (manage_options)'=>'صرف ایڈمنسٹریٹرز (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'پہلی زبان تبدیل کرنے کے بعد، URL راؤٹنگ کو اپ ڈیٹ کرنے کے لیے پرم لنکس کو فلش کریں (نیچے سیکشن)۔','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'URL ساخت کی ترتیبات (پاتھ پری فکس ↔ سب ڈومین) تبدیل کرنے کے بعد، ہمیشہ سیٹنگز → پرمالنکس پر جائیں اور ری وائیٹ قوانین کو فلش کرنے کے لیے سیو تبدیلیاں کریں۔','AI analysis failed. Please try again.'=>'AI تجزیہ ناکام رہا۔ براہ کرم دوبارہ کوشش کریں۔','AI Behaviour Preset'=>'AI رویہ پری سیٹ','AI cache cleared. %d entry was removed.'=>'ای اے آئی کیش صاف کر دی گئی۔ %d اندراج ہٹا دی گئی۔' . "\0" . 'ای اے آئی کیش صاف کر دی گئی۔ %d اندراجات ہٹا دی گئی ہیں۔','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'AI کیش: کیش شدہ AI جوابات کی فہرستیں ہٹ کاؤنٹس کے ساتھ۔ پورے کیش کو یا ایک مخصوص پوسٹ کی انٹریز کو صاف کریں۔ ترجمہ میں تبدیلی سے پہلے "کلئیر" کا استعمال کریں — کیش شدہ نتائج واپس آتے ہیں یہاں تک کہ آپ AI پری سیٹ یا ماڈل کو تبدیل کریں، جب تک کہ کیش انٹری کو نکال نہ دیا جائے۔','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'AI کی خصوصیات اختیاری ہیں۔ زبان کی رہنمائی، hreflang، زبان سوئچر، اور ترجمہ گروپ سسٹم سب بغیر کسی فراہم کنندہ کے ترتیب کے کام کرتے ہیں۔','AI Limits & Security'=>'AI کی حدیں اور سیکیورٹی','AI provider returned an empty response.'=>'AI فراہم کنندہ نے خالی جواب دیا۔','AI Recommendations'=>'AI سفارشات','AI returned an unexpected response format. Please try again.'=>'AI نے غیر متوقع جواب دیا ہے۔ براہ کرم دوبارہ کوشش کریں۔','AI Usage'=>'AI استعمال','AI Usage & Cache'=>'AI استعمال اور کیش','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'120–160 حروف کا ہدف۔ خالی چھوڑیں تاکہ خلاصہ کا استعمال ہو۔','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'تمام بڑے سرچ انجن — Google، Bing، اور Yandex — خودکار طور پر Sitemap: ہدایت کے ذریعے سائیٹ میپ دریافت کرتے ہیں۔ کوئی دستی کارروائی ضروری نہیں ہے۔ نیچے دیے گئے بٹن فوری پنگ بھیجتے ہیں تاکہ انجن اب ہی سائیٹ میپ کو دوبارہ اسکین کرے، نہ کہ اگلی شیڈول شدہ robots.txt چیک کا انتظار کرے۔','All time'=>'تمام وقت','All types'=>'تمام اقسام','Allow editors to lock individual blocks'=>'ایڈیٹرز کو اجازت دیں کہ وہ انفرادی بلاکس کو لاک کریں','Allow Gutenberg template-editing mode on post screens'=>'پوسٹ اسکرین پر Gutenberg ٹیمپلیٹ ایڈیٹنگ موڈ کی اجازت دیں','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'جب پلگ ان ان انسٹال کیا جائے تو زبان کی تفویض، ترجمہ کے تعلقات، میٹا تفصیلات، گلاسری، اور ترجمہ یادداشت بھی حذف کریں۔','Also generate meta description'=>'میٹا تفصیل بھی تیار کریں','Alternative (server-side):'=>'متبادل (سرور-سائیڈ):','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'ہمیشہ صرف og:locale اور og:locale:alternate خارج کریں۔ جب کوئی دوسرا پلگ ان یا تھیم مکمل OG سیٹ سنبھال رہا ہو تو استعمال کریں۔','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'ہمیشہ مکمل OG + Twitter Card سیٹ خارج کریں، چاہے دوسرے پلگ انز کچھ بھی کریں۔ صرف اس صورت میں استعمال کریں جب کوئی دوسرا پلگ ان OG ٹیگز پیدا نہ کرتا ہو۔','An unknown error occurred.'=>'ایک نامعلوم غلطی پیش آئی۔','Analyse…'=>'تجزیہ…','Analysis'=>'تجزیہ','Analysis request failed. Please try again.'=>'تجزیہ درخواست ناکام رہی۔ براہ کرم دوبارہ کوشش کریں۔','Analyzing…'=>'تجزیہ جاری ہے…','and'=>'اور','Anthropic (Claude)'=>'انتھروپک (کلود)','any'=>'کچھ بھی','API calls saved by cache'=>'کیش شدہ API کالز','API Key'=>'API کلید','API Keys'=>'API کیز','API Keys Tab'=>'API کیز ٹیب','API Response Cache'=>'API جواب کیش','Appends the following line to your existing robots.txt: %s'=>'آپ کے موجودہ robots.txt میں درج ذیل لائن شامل کرتا ہے: %s','Applied ✓'=>'درخواست دی گئی ✓','Apply failed — please try again.'=>'درخواست ناکام — براہ کرم دوبارہ کوشش کریں۔','Apply to Block'=>'بلاک پر لاگو کریں','Apply to Editor'=>'ایڈیٹر میں لاگو کریں','Apply to Footnote'=>'حاشیہ پر لاگو کریں','Apply to Meta Description'=>'میٹا تفصیل پر لاگو کریں','Apply translation'=>'ترجمہ لاگو کریں','Applying…'=>'درخواست دی جا رہی ہے…','Approximate size'=>'تقریبی سائز','Archive'=>'آرکائیو','Archive: %s'=>'آرکائیو: %s','Article / WebPage'=>'مضمون / ویب پیج','Article / WebPage — all singular posts and pages'=>'مضمون / ویب پیج — تمام واحد پوسٹس اور صفحات','Authors and above (edit_published_posts)'=>'مصنفین اور اوپر (edit_published_posts)','Auto (recommended)'=>'خودکار (تجویز کردہ)','Behavior'=>'رویہ','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'رویہ: AI پری سیٹ منتخب کریں (مطلق، متوازن، تخلیقی)، سائٹ بھر میں کسٹم پرامپٹ ہدایات شامل کریں، خودکار پوسٹ سیو ترجمہ کو فعال یا غیر فعال کریں، اور ترجمہ یادداشت کو ترتیب دیں۔','Block Content'=>'بلاک مواد','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'ایک مہذب نوٹس ظاہر کرتا ہے جب موجودہ صفحہ اپنی اصل زبان میں دکھایا جا رہا ہو کیونکہ زائرین کی زبان کے لیے کوئی ترجمہ موجود نہیں ہے۔ یہ Lingua Forge روٹر کے LINGUAFORGE_LANG_FALLBACK_ACTIVE سگنل سے چلتا ہے — جب درخواست کے لوکل کے لیے ترجمہ موجود ہو تو کچھ بھی خارج نہیں ہوتا۔','Block Editor'=>'بلوک ایڈیٹر','block keywordfallback'=>'واپسی','block keywordi18n'=>'آئی18این','block keywordlanguage'=>'زبان','block keywordlinguaforge'=>'لینگوا فورج','block keywordtranslation'=>'ترجمہ','Block locking'=>'بلوک لاک کرنا','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'کسٹم پوسٹ ٹائپز کے لیے رجسٹرڈ بلاک پیٹرنز۔ ترجمہ بٹن کا استعمال کریں تاکہ زبان کا ورژن تیار کیا جا سکے۔ ترجمہ شدہ مواد یہاں محفوظ کیا جاتا ہے اور کسی بھی CPT پوسٹ میں کاپی کیا جا سکتا ہے یا سنیپڈ پیٹرن (ری یوزبل بلاک) کے لیے بطور آغاز استعمال کیا جا سکتا ہے۔','block titleMissing Translation Notice'=>'مفقود ترجمہ نوٹس','Block translation reuses'=>'ترجمہ کی بلاک ری یوز','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'بلاک سطح کی ترجمہ کیش جو پوسٹس کے درمیان مشترک ہے۔ فعال ہونے پر، ایک جیسی بلاکس (ایک جیسا مارک اپ، زبان کا جوڑا، اور گلاسری) کو یادداشت سے فراہم کیا جاتا ہے بجائے اس کے کہ AI کو دوبارہ کال کریں۔ سیٹنگز → رویہ میں ترتیب دیں۔','Blog / Editorial'=>'بلاگ / اداریہ','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'بلاگ پوسٹس کو Article استعمال کریں؛ دیگر تمام پوسٹ اقسام اور صفحات WebPage استعمال کرتے ہیں۔ اس میں سرخی، تفصیل، inLanguage، url، تاریخ اشاعت، تاریخ ترمیم، تصویر، اور پبلشر شامل ہیں۔','Browser language redirect'=>'براؤزر زبان ری ڈائریکشن','Built-in preset instructions:'=>'بلٹ ان پری سیٹ ہدایات:','Bulletize (•-prefixed)'=>'بولٹائز کریں (•-پیش شدہ)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'ترجمہ شدہ مساوی کو بلاک سطح پر کیش کریں تاکہ قابل استعمال مواد (مشترکہ فوٹرز، سائیڈبارز، ایکورڈینز، قانونی سیکشنز) ہر بار API کال نہ کریں۔ فعال ہونے پر، ترجمہ کا عمل ہر پوسٹ کو بلاکس میں پارس کرتا ہے، ہر بلاک کو کیش میں دیکھتا ہے، اور صرف ان بلاکس کو AI کو بھیجتا ہے جو کیش میں نہیں ہیں۔ گلاسری میں ترمیم اور تعمیل پری سیٹ میں تبدیلیاں خود بخود متاثرہ کیش شدہ ترجمہ کو منسوخ کرتی ہیں۔ اعداد و شمار دیکھیں اور کیش صاف کریں۔','cached'=>'کیش شدہ','Cached API responses'=>'کیش شدہ API جوابات','Cached block translations'=>'کیش شدہ بلاک ترجمے','Cancel'=>'منسوخ کریں','Cannot determine target language from slug.'=>'ہدف زبان slug سے معلوم نہیں ہو سکی۔','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'پروڈکٹ %1$d پر لکھنے سے قاصر ہے: یہ ترجمہ شدہ ورژن ہے (زبان: %2$s)%3$s۔ آپریشنل ڈیٹا (قیمت، اسٹاک، SKU، ابعاد) کو ماخذ پروڈکٹ پر اپ ڈیٹ کرنا چاہیے۔ ماخذ پروڈکٹ ID کو حل کریں: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>'کنونینل ٹیگ','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'سائٹ کی AI استعمال کی حد مقرر کریں اور ان صارف کرداروں کو محدود کریں جو ادائیگی شدہ AI کالز کو چلا سکتے ہیں۔ یہ پہلے سے موجود فی صارف شرح حد (30 درخواستیں / منٹ، ہارڈ کوڈڈ) کے اوپر بیٹھتی ہے جو ایک صارف کے رن وے لوپ سے بچاؤ کرتی ہے۔','chars'=>'حروف','Chunk translated'=>'ٹکڑا ترجمہ شدہ','Chunk translated to:'=>'ٹکڑا ترجمہ ہوا:','Clear'=>'صاف کریں','Clear All'=>'سب کچھ صاف کریں','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'تمام کیش شدہ AI نتائج کو صاف کریں؟ مستقبل کی درخواستیں تازہ API کالز کو متحرک کریں گی جب تک کہ کیش دوبارہ نہ بن جائے۔','Clear API Response Cache'=>'API جواب کیش کو صاف کریں','Clear Debug Files'=>'ڈیبگ فائلیں صاف کریں','Clear hints'=>'اشارے صاف کریں','Clear input'=>'ان پٹ صاف کریں','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'کیا آپ ترجمہ یادداشت کو مکمل طور پر صاف کرنا چاہتے ہیں؟ مستقبل کے ترجمے اسے دوبارہ بنائیں گے۔','Clear Translation Memory'=>'ترجمہ یادداشت صاف کریں','Close'=>'بند کریں','Close language panel'=>'زبان پینل بند کریں','Close popover'=>'پاپ اوور بند کریں','Compatibility'=>'مطابقت','Compliance Preset'=>'مطابقت کا پری سیٹ','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'سیٹنگز → API Keys میں ایک AI فراہم کنندہ کو ترتیب دیں تاکہ AI کی طاقت سے سفارشات فعال ہوں۔','Content generated'=>'مواد تیار','Content Generator'=>'مواد پیدا کرنے والا','Content ready'=>'مواد تیار ہے','Contributors and above — default (edit_posts)'=>'شریک کار اور اوپر — ڈیفالٹ (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'کنٹرول کریں کہ مواد کو AI کو کتنا بھیجا جائے اور جواب کتنا بڑا ہو سکتا ہے۔ ایک فیلڈ کو خالی چھوڑیں تاکہ اندرونی ڈیفالٹ استعمال ہو (جیسے پلیس ہولڈر میں دکھایا گیا ہے)۔ اگر بڑی صفحات کاٹ دی جا رہی ہیں تو ان اقدار کو بڑھائیں؛ API کے اخراجات کم کرنے کے لیے انہیں کم کریں۔','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'ای اے آئی مواد پیدا کرنے والے فیچر کے لیے ٹوکن بجٹ اور ان پٹ حدود کو کنٹرول کرتا ہے۔ بلینک فیلڈز کو چھوڑیں تاکہ بلٹ ان ڈیفالٹس استعمال ہوں۔','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'جب ایڈمنسٹریٹر Plugins → Installed Plugins → Delete سے پلگ ان کو حذف کرتا ہے تو یہ کنٹرول کرتا ہے کہ کیا ہوتا ہے۔ پلگ ان کی سیٹنگز اور اے آئی کیش ہمیشہ ہٹائے جاتے ہیں۔ زبان کی تفویض اور ترجمہ کے تعلقات کو بطور ڈیفالٹ رکھا جاتا ہے تاکہ حادثاتی ان انسٹال یا دوبارہ انسٹال پر وہیں سے شروع کیا جا سکے۔','Conversational'=>'بات چیت','Copied ✓'=>'کاپی کیا ✓','Copy'=>'نقل کریں','Copy failed — please copy the URL manually.'=>'کاپی ناکام — براہ کرم URL کو دستی طور پر کاپی کریں۔','Copy markup'=>'مارک اپ کاپی کریں','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'موجودہ URL کو کلپ بورڈ پر کاپی کریں۔ کامیابی پر "Link copied" ٹوسٹ دکھائے گا۔','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'نتیجہ کو کاپی کریں اور جہاں ضرورت ہو چپکائیں (مثلاً، براہ راست حاشیہ کے میدان میں)۔','Copy to safe storage'=>'محفوظ اسٹوریج پر کاپی کریں','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'کاپی/مقامی/خودکار JS کارروائیاں: LF کے سوشل شیئر.js کے ذریعے ہینڈل کی گئی ہیں','Could not add entry: source term and target term are required.'=>'داخلہ شامل نہیں کیا جا سکا: ماخذ اصطلاح اور ہدف اصطلاح ضروری ہیں۔','Could not copy the file. Check that the uploads folder is writable.'=>'فائل کو کاپی نہیں کیا جا سکا۔ چیک کریں کہ اپ لوڈز فولڈر قابل تحریر ہے۔','Could not instantiate the provider.'=>'فراہم کنندہ کو شروع نہیں کیا جا سکا۔','Could not save the file. Check that the uploads folder is writable.'=>'فائل کو محفوظ نہیں کیا جا سکا۔ چیک کریں کہ اپ لوڈز فولڈر قابل تحریر ہے۔','Could not save the glossary entry.'=>'مفہومیہ داخلہ محفوظ نہیں کیا جا سکا۔','Could not write to robots.txt. Check file permissions.'=>'robots.txt میں لکھنے سے قاصر۔ فائل کی اجازتیں چیک کریں۔','CPT Block Patterns'=>'CPT بلاک پیٹرنز','Create'=>'بنائیں','Create missing'=>'غائب تخلیق کریں','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'پوسٹ قسم "%s" کے لیے ترجمہ تخلیق کرنے کے لیے ایک فعال انٹیگریشن درکار ہے۔ براہ کرم یقینی بنائیں کہ مطلوبہ انٹیگریشن انسٹال اور فعال ہے۔','Creating…'=>'درست ہو رہا ہے…','Creative / Marketing'=>'تخلیقی / مارکیٹنگ','Creative / Marketing instructions'=>'تخلیقی / مارکیٹنگ ہدایات','Current content (will be overwritten)'=>'موجودہ مواد (اوور رائٹ کیا جائے گا)','Current status'=>'موجودہ حالت','Current title'=>'موجودہ عنوان','Current: {current}'=>'موجودہ: {current}','Currently emitting'=>'اس وقت خارج ہو رہا ہے','Currently inherited from the %s constant. Selecting a value here will override it.'=>'اس وقت %s مستقل سے وراثت میں ملا ہوا ہے۔ یہاں ایک قیمت منتخب کرنے سے اسے اوور رائیڈ کیا جائے گا۔','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'اس وقت ان پوسٹس کے لیے چھوڑ دیا گیا ہے جو بلاک-تبصرہ خصوصیت کے پلیس ہولڈرز استعمال کرتی ہیں (wp:details خلاصہ فیلڈز، وغیرہ) — یہ موجودہ سنگل-کال ترجمہ راستے سے گرتی ہیں۔','Currently:'=>'اس وقت:','Custom'=>'حسبِ ضرورت','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'روزانہ AI کوٹہ مکمل ہو گیا (%1$d درخواستیں)۔ %2$s UTC پر ری سیٹ ہوتا ہے۔','Daily request limit'=>'روزانہ درخواست کی حد','Danger Zone'=>'خطرناک علاقہ','Debug Files'=>'ڈیبگ فائلیں','Debug files cleared. %d file was removed.'=>'ڈیبگ فائلیں صاف کی گئی۔ %d فائل ہٹا دی گئی۔' . "\0" . 'ڈیبگ فائلیں صاف کی گئی۔ %d فائلیں ہٹا دی گئی ہیں۔','Debug logging'=>'ڈیبگ لاگنگ','Debug logging disabled.'=>'ڈیبگ لاگنگ غیر فعال ہے۔','Debug logging enabled.'=>'ڈیبگ لاگنگ فعال ہے۔','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'ڈیبگ: AI پرامپٹس اور API جوابات کو ایک مقامی فائل میں ریکارڈ کرنے کے لیے ڈیبگ لاگ فعال کریں۔ مسئلہ حل کرنے کے بعد غیر فعال کریں — ڈیبگ موڈ ہر AI درخواست پر ایک فائل لکھتا ہے۔','Default OG image'=>'پہلے سے طے شدہ OG تصویر','Delete'=>'حذف کریں','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'کیا آپ ڈیبگ ڈائریکٹری میں تمام .txt فائلیں حذف کرنا چاہتے ہیں؟ خود ڈائریکٹری باقی رہے گی تاکہ مستقبل میں ڈیبگ لکھائی آسانی سے ہو سکے۔ آپ اسے wp-config.php سے بھی فورس کر سکتے ہیں `define( \'LINGUAFORGE_AI_DEBUG\', true );` کے ساتھ جو ٹوگل کو اوور رائیڈ کرتا ہے۔','Delete all files for this override (both .mo and .po)?'=>'اس اوور رائڈ کے لیے تمام فائلیں حذف کریں (دونوں .mo اور .po)؟','Delete content data on uninstall'=>'ان انسٹال پر مواد کا ڈیٹا حذف کریں','Delete this glossary entry?'=>'کیا آپ اس مفہومیہ داخلہ کو حذف کرنا چاہتے ہیں؟','Describe what to write — topic, key points, structure…'=>'بتائیں کہ کیا لکھنا ہے — موضوع، اہم نکات، ساخت…','Details ↗'=>'تفصیلات ↗','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'رَن ٹائم پر فعال SEO پلگ انز (Yoast، Rank Math، وغیرہ) کا پتہ لگائیں۔ جب کوئی اور پلگ ان پہلے سے مکمل OG سیٹ آؤٹ پٹ کر رہا ہو تو صرف og:locale + og:locale:alternate خارج کریں؛ جب کوئی بھی نہیں پایا جائے تو مکمل سیٹ خارج کریں۔','Directory'=>'ڈائریکٹری','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'پرامپٹ ٹیوننگ کے دوران یا جب آپ کو ہر درخواست AI فراہم کنندہ تک پہنچنی ہو، اس وقت غیر فعال کریں۔ غیر فعال کرنے سے کیش شدہ انٹریز حذف نہیں ہوتی — دوبارہ فعال کرنے سے وہ بحال ہو جاتی ہیں۔ مصروف سائٹس پر فوری API خرچ میں اضافہ متوقع ہے جب یہ غیر فعال ہو۔','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'صرف ہیڈلیس سائٹس یا مکمل طور پر کسٹم hreflang نفاذ کے لیے غیر فعال کریں۔ جب غیر فعال کیا جائے، تو LF اب WordPress کے بنیادی canonical ٹیگ کو ہٹانا بند کر دیتا ہے اور SEO-پلگ ان کے hreflang آؤٹ پٹ کو بھی روک دیتا ہے۔','Disabled'=>'غیر فعال','Disabled (by setting)'=>'غیر فعال (سیٹنگ کے ذریعے)','Disabled (mode setting)'=>'غیر فعال (موڈ سیٹنگ کے ذریعے)','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'پہلے سے ہی lf-social-share mu-پلاگ ان یہ خصوصیت فراہم کر رہا ہے اس لیے غیر فعال۔','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS سیٹ ہے۔','Display'=>'ظاہر کریں','Displays the Lingua Forge language switcher.'=>'لینگوا فورج زبان سوئچر دکھاتا ہے۔','Do not output any OG tags.'=>'کسی بھی OG ٹیگ کو آؤٹ پٹ نہ کریں۔','Documentation'=>'دستاویزات','Done'=>'ہو گیا','Done — {done} of {total} post(s) fixed.'=>'ہو گیا — {done} میں سے {total} پوسٹیں ٹھیک کی گئیں۔','Down'=>'نیچے','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'ورڈپریس.org سے براہ راست ورڈپریس کور زبان پیک ڈاؤن لوڈ اور انسٹال کریں۔ ایک بار انسٹال ہونے کے بعد، لوکیل URL روٹنگ اور AI ترجمہ ورک فلو کے لیے دستیاب ہو جاتا ہے۔ دستیاب زبانوں کی فہرست ضرورت کے مطابق حاصل کی جاتی ہے — اسے لوڈ کرنے کے لیے نیچے بٹن پر کلک کریں۔','Dropdown direction'=>'ڈراپ ڈاؤن سمت','edit'=>'ترمیم کریں','Editors and above (edit_others_posts)'=>'ایڈیٹرز اور اوپر (edit_others_posts)','Enable API response caching'=>'API جواب کیشنگ فعال کریں','Enable block-level translation cache reuse across posts'=>'پوسٹس کے درمیان بلاک سطح کی ترجمہ کیش کا استعمال فعال کریں','Enable Social Share URL rewriting for Social Icons blocks'=>'سوشل آئیکنز بلاک کے لیے سوشل شیئر URL ری رائٹنگ فعال کریں','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'جب آپ کا تھیم پوسٹ کے عنوان کو H2 کے طور پر رینڈر کرتا ہے اور H1 کے طور پر نہیں (کچھ بلاک تھیمز میں عام) تو فعال کریں۔ تجزیہ کار رینڈر شدہ صفحہ کو حاصل کرتا ہے اور اگر اسے کوئی H1 نہیں ملتا لیکن H2 ملتی ہے، تو یہ پہلے H2 کو H1 میں تبدیل کرتا ہے تاکہ اسکورنگ کے لیے۔','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'کم از کم ایک AI فراہم کنندہ کے لیے اپنی API کلید درج کریں۔ کلیدیں AES-256-GCM کے ساتھ ایک مخصوص سائٹ کے راز (LINGUAFORGE_SECRET) کا استعمال کرتے ہوئے انکرپٹ کی جاتی ہیں۔ بغیر راز کو تبدیل کیے ڈیٹا بیس ایکسپورٹس شیئر نہ کریں۔','environment variable'=>'ماحولیاتی متغیر','Error'=>'خرابی','Expand'=>'وسیع کریں','Expected: {expected}'=>'متوقع: {expected}','External share services'=>'باہر سے شیئر سروسز','Extra guidance — tone, style, constraints, target audience…'=>'اضافی رہنمائی — لہجہ، انداز، پابندیاں، ہدفی سامعین…','Extra guidance — tone, style, constraints…'=>'اضافی رہنمائی — لہجہ، انداز، پابندیاں…','Failed. Please try again.'=>'ناکام۔ براہ کرم دوبارہ کوشش کریں۔','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'جب کسی صفحہ میں نمایاں تصویر، سائٹ لوگو، یا سائٹ آئیکن نہ ہو تو استعمال ہونے والی فالو اپ تصویر URL۔ آرکائیوز، بلاگ انڈیکس، اور کسی بھی سنگل پیج کے لیے سوشل پریویو میں دکھائی دیتی ہے۔','Feature'=>'خصوصیت','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'خصوصیات کو دو سطحوں میں گروپ کیا گیا ہے۔ ہر سطح اور فراہم کنندہ کے لیے بالکل درست ماڈل شناخت کنندہ درج کریں۔ خالی چھوڑیں تاکہ بلٹ ان ڈیفالٹ استعمال کیا جا سکے۔ صرف فعال فراہم کنندہ کے ماڈلز کو رن ٹائم پر کال کیا جاتا ہے — اگر آپ سوئچ کرنے کا ارادہ رکھتے ہیں تو دیگر کو پہلے سے ترتیب دیں۔','File copied to safe storage successfully.'=>'فائل کامیابی سے محفوظ اسٹوریج میں کاپی ہو گئی۔','File modifications are disabled (DISALLOW_FILE_MODS).'=>'فائل میں ترمیمات غیر فعال ہیں (DISALLOW_FILE_MODS)۔','Files'=>'فائلیں','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'فائلیں نیچے دیے گئے ڈائریکٹری میں آتی ہیں۔ ترجمہ کے مسائل کی تشخیص کے لیے مفید — ایک بار جب آپ کو ضرورت ہو تو بند کریں تاکہ فائلیں جمع نہ ہوں۔ آپ اسے wp-config.php سے بھی فورس کر سکتے ہیں `define( \'LINGUAFORGE_AI_DEBUG\', true );` کے ساتھ جو ٹوگل کو اوور رائیڈ کرتا ہے۔','Filter'=>'فلٹر','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'زبان اور پوسٹ قسم کے لحاظ سے فلٹر کریں، اپنی مواد براؤز کریں، اور کسی بھی آئٹم پر تجزیہ کریں تاکہ قواعد پر مبنی SEO آڈٹ چلایا جا سکے — عنوان کی لمبائی، میٹا تفصیل، الفاظ کی تعداد، سرخی کا ڈھانچہ، تصویر کے متبادل کا احاطہ، اور داخلی روابط۔','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'ڈیبگ آؤٹ پٹ کو غیر عوامی مقام پر ری ڈائریکٹ کرنے کے لیے linguaforge_debug_dir کے ساتھ فلٹر کریں۔','Finding'=>'پایا جا رہا ہے','Fix'=>'مرمت کریں','Fix All'=>'سب کو درست کریں','Fix all links'=>'تمام روابط درست کریں','Fix all parts'=>'تمام حصے درست کریں','Fix Links'=>'لنکس کو درست کریں','Fix Nav'=>'نیویگیشن کو درست کریں','Fix Parts'=>'پارٹس کو درست کریں','Fix Template'=>'ٹیمپلیٹ درست کریں','Fixing {n} / {total}…'=>'{n} / {total} کی مرمت جاری ہے…','Fixing…'=>'درست کر رہا ہے…','Flush Permalink Rules'=>'پرم لنک قواعد کو فلش کریں','Flush Permalinks'=>'پرم لنکس کو فلش کریں','Flush Sitemap Cache'=>'سائٹ میپ کیشے کو فلش کریں','Footnote Content'=>'حاشیہ مواد','footnote(s) translated — applied together with content.'=>'حاشیہ جات ترجمہ شدہ — مواد کے ساتھ مل کر لاگو کیا گیا۔','Footnotes'=>'حاشیہ جات','Footnotes payload (advanced)'=>'حاشیہ نوٹس (ایڈوانسڈ)','Forbidden'=>'ممنوع','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.php میں LINGUAFORGE_AI_DEBUG مستقل کے ذریعے زبردستی آف۔ اس لائن کو ہٹا کر اس ٹوگل کو یہاں سے کنٹرول کریں۔','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.php میں LINGUAFORGE_AI_DEBUG مستقل کے ذریعے زبردستی آن۔ اس لائن کو ہٹا کر اس ٹوگل کو یہاں سے کنٹرول کریں۔','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'اگلی درخواست پر سائٹ میپ کو دوبارہ پیدا کرنے پر مجبور کرتا ہے۔ بڑے پیمانے پر درآمد یا ترجمہ تعلقات کو دستی طور پر ترمیم کرنے کے بعد استعمال کریں۔','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'پائے گئے {parts} <strong>{total}</strong> میں سے <strong>{scanned}</strong> اسکین شدہ پوسٹ/صفحات کے لیے <strong>{lang}</strong>۔','From'=>'سے','Front Page'=>'فرنٹ پیج','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSE لوکلائزیشن: اس ٹیب سے براہ راست فُل سائٹ ایڈیٹنگ ٹیمپلیٹس اور ٹیمپلیٹ پارٹس میں اسکافولڈ، ترجمہ، اور لنکس کی مرمت کریں۔','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'فعال تھیم سے سیڈ شدہ FSE ٹیمپلیٹس۔ اسے بنائیں اور پھر سائٹ ایڈیٹر میں تخصیص کریں۔','Full'=>'مکمل','Full Article'=>'مکمل مضمون','Full post'=>'مکمل پوسٹ','General'=>'عام','Generate'=>'پیدا کریں','Generate Content'=>'مواد تیار کریں','Generate content…'=>'مواد تیار کریں…','Generate Excerpt'=>'خلاصہ تیار کریں','Generate Meta Description'=>'میٹا تفصیل تیار کریں','Generate the multilingual sitemap at /lf-sitemap.xml'=>'کثیر لسانی سائٹ میپ کو /lf-sitemap.xml پر پیدا کریں','Generated Content'=>'تیار کردہ مواد','Generated meta description'=>'تیار کردہ میٹا تفصیل','Generating…'=>'پیدا ہو رہا ہے…','Generation failed.'=>'پیداوار ناکام۔','Getting started'=>'شروع کرنا','Global AI preset'=>'عالمی AI پری سیٹ','Global default (%s)'=>'عالمی ڈیفالٹ (%s)','Glossary'=>'گلاسری','Glossary entry added.'=>'مفہومیہ داخلہ شامل کیا گیا۔','Glossary entry removed.'=>'مفہومیہ داخلہ ہٹا دیا گیا۔','Glossary Tab'=>'گلاسری ٹیب','Google (Gemini)'=>'گوگل (جمینی)','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'H2-بطور-H1 موڈ فعال — عنوان کو H1 کے مساوی شمار کیا جاتا ہے۔ (ہیڈنگ ٹیگز رینڈر شدہ صفحہ سے معلوم نہیں ہو سکے؛ اپنے تھیم کے عنوان کو صحیح طریقے سے آؤٹ پٹ کرنے کی تصدیق کریں۔)','Headings'=>'سرخیاں','Hide'=>'چھپائیں','Hints'=>'اشارات','Home link text'=>'ہوم لنک کا متن','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'ترجمہ میں یہ کس طرح ظاہر ہونا چاہیے۔ AI کو ہدایت دینے کے لیے ماخذ اصطلاح کے طور پر وہی قدر ٹائپ کریں تاکہ اسے حرف بہ حرف محفوظ رکھا جائے۔','How to use'=>'استعمال کا طریقہ','Hreflang'=>'Hreflang','Hreflang output'=>'Hreflang آؤٹ پٹ','Hreflang settings saved.'=>'Hreflang سیٹنگز محفوظ ہو گئی ہیں۔','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'آئیکن + لیبل','Icon only'=>'صرف آئیکن','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'اگر چیک کیا گیا، تو پلگ ان ان انسٹال کرنے سے تمام زبان کی تفویض، ترجمہ کے تعلقات، میٹا تفصیلات، صفحات کے پری سیٹ، اے آئی گلاسری، اور ترجمہ یادداشت ہمیشہ کے لیے حذف ہو جائیں گی۔ یہ عمل واپس نہیں لیا جا سکتا۔ جب تک کہ آپ مکمل طور پر ملٹی لنگول سپورٹ کو ہٹا رہے ہوں، اسے ان چیک چھوڑیں۔','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'اگر آپ کے پاس کوئی عمومی SEO پلگ ان نصب ہے، تو یہ پینل دکھاتا ہے کہ LF کس طرح نقل سے بچاؤ کے لیے مطابقت رکھتا ہے۔ مقصد تصادم سے بچاؤ ہے — تعاون نہیں۔ LF ہمیشہ کثیر لسانی SEO پرت فراہم کرتا ہے (hreflang، og:locale، inLanguage schema) جو LF کی زبان کی روٹنگ کنفیگریشن کے علم کے بغیر صحیح پیدا کرنا مشکل ہے۔','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'اگر آپ کے پاس Yoast SEO، Rank Math، All in One SEO، یا SEOPress نصب ہے، تو Lingua Forge انہیں پہچانتا ہے اور نقل سے بچاؤ کے لیے مطابقت رکھتا ہے۔ hreflang کے لیے، LF مکمل طور پر قبضہ کرتا ہے اور پلگ ان کے آؤٹ پٹ کو روکتا ہے کیونکہ یہ پلگ ان کثیر لسانی روٹنگ کنفیگریشن کے لیے صحیح hreflang پیدا نہیں کر سکتے۔ Open Graph کے لیے، LF صرف og:locale اور og:locale:alternate شامل کرتا ہے — وہ کثیر لسانی سگنلز جو پلگ ان فراہم نہیں کر سکتا — اور بنیادی OG سیٹ کو پلگ ان پر چھوڑ دیتا ہے۔ Schema.org کے لیے، LF اپنی آؤٹ پٹ کو مکمل طور پر غیر فعال کر دیتا ہے تاکہ متصادم JSON-LD گراف سے بچا جا سکے۔','Images'=>'تصاویر','Improve writing'=>'تحریر بہتر بنائیں','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'بلاک ایڈیٹر میں، ایک سوشل آئیکنز بلاک شامل کریں۔ ہر آئیکن کے لیے، لنک سیٹنگز کھولیں اور نیچے دیے گئے "share:" ویلیوز میں سے ایک کو URL کے طور پر درج کریں۔ فرنٹ اینڈ پر، LF اسے موجودہ صفحہ کے صحیح شیئر URL سے بدل دیتا ہے۔','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'اس میں نام، تفصیل، inLanguage، url، تصویر، اور ایک آفر شامل ہے جس میں قیمت، قیمت کرنسی، اور دستیابی شامل ہے۔ قیمت اور دستیابی ماخذ زبان کے پروڈکٹ سے آتی ہے (مشترکہ اسٹاک ماڈل)۔','Includes site name, url, and inLanguage.'=>'اس میں سائٹ کا نام، url، اور inLanguage شامل ہے۔','Informative'=>'معلوماتی','Input tokens'=>'انپٹ ٹوکنز','Install'=>'انسٹال کریں','Install a Language'=>'ایک زبان انسٹال کریں','Installed SEO plugins'=>'انسٹال شدہ SEO پلگ انز','Installing…'=>'انسٹال ہو رہا ہے…','instock / oos / pending from WC stock status'=>'WC اسٹاک کی حالت سے ان اسٹاک / او او ایس / زیر التواء','Instructions (optional)'=>'ہدایات (اختیاری)','Instructions / key points'=>'ہدایات / اہم نکات','Integration API'=>'انٹیگریشن API','Internal Link Fixer'=>'اندرونی لنک مرمت کرنے والا','Introduction only'=>'صرف تعارف','Invalid file reference.'=>'غلط فائل کا حوالہ۔','Invalid filename.'=>'غلط فائل کا نام۔','Invalid language code.'=>'غلط زبان کا کوڈ۔','Invalid language.'=>'غلط زبان۔','Invalid locale code.'=>'غلط لوکیل کوڈ۔','Invalid or primary language.'=>'غلط یا بنیادی زبان۔','Invalid post ID.'=>'غلط پوسٹ ID۔','Invalid post type.'=>'غلط پوسٹ قسم۔','Invalid template part.'=>'غلط سانچہ حصہ۔','Invalid template type.'=>'غلط سانچہ قسم۔','JavaScript-powered actions'=>'جاوا اسکرپٹ سے چلنے والی کارروائیاں','Key points, ideas, or structure to build from…'=>'اہم نکات، خیالات، یا ساخت جس سے تعمیر کی جائے…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'کیز کو AES-256-CBC کے ساتھ انکرپٹ کیا جاتا ہے قبل اس کے کہ وہ ورڈپریس کے ڈیٹا بیس میں محفوظ ہوں۔ انکرپشن کا راز آپ کے ورڈپریس کے تصدیقی نمک (wp-config.php) سے حاصل کیا جاتا ہے، اس لیے سادہ متن کی کیز کبھی بھی ڈیٹا بیس کو نہیں چھوتی۔','Landing / Short-form'=>' لینڈنگ / مختصر شکل','Language'=>'زبان','Language %s installed successfully.'=>'زبان %s کامیابی سے انسٹال ہو گئی ہے۔','Language (optional)'=>'زبان (اختیاری)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'اس سرور پر زبان کی تنصیب غیر فعال ہے (DISALLOW_FILE_MODS سیٹ ہے)۔','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'اس سرور پر زبان کی تنصیب غیر فعال ہے۔ wp-config.php میں DISALLOW_FILE_MODS مستقل سیٹ ہے۔ زبان پیکز کو دستی طور پر WP-CLI کے ذریعے انسٹال کریں: wp language core install de_DE','Language label'=>'زبان کا لیبل','Language Overrides'=>'زبان کی تبدیلی','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'زبان کی اوور رائڈز: لینگوہ فورج UI سٹرنگز کے لیے کسٹم .po/.mo فائلیں منظم کریں۔ اسے پلگ ان فائلوں میں ترمیم کرنے کے بجائے استعمال کریں — اوور رائڈز اپڈیٹس کے دوران برقرار رہتی ہیں۔','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'زبان پیک انسٹالیشن ناکام ہو گئی۔ زبان پہلے سے انسٹال ہو سکتی ہے، لوکیل کوڈ غلط ہو سکتا ہے، یا آپ کا سرور فائل لکھنے سے روک رہا ہے۔','Language Setup'=>'زبان کی سیٹ اپ','Language Switcher'=>'زبان سوئچر','Language switcher'=>'زبان سوئچر','Language uninstalled. %d post deleted.'=>'زبان ان انسٹال ہو گئی ہے۔ %d پوسٹ حذف کی گئی۔' . "\0" . 'زبان ان انسٹال ہو گئی ہے۔ %d پوسٹس حذف کی گئی۔','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'تھیم کے زبان مخصوص نقول۔ ایک بار اسکافولڈ ہونے کے بعد، ٹیمپلیٹس زبان مخصوص پارٹ کا حوالہ دینے کے لیے اپ ڈیٹ ہو جاتے ہیں۔','Language:'=>'زبان:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'روٹر کو معلوم زبانیں (انسٹال شدہ ورڈپریس لوکیل پیکز اور بنیادی زبان سے حاصل شدہ)۔ مزید زبانیں دستیاب کرنے کے لیے ذیل کے سیکشن میں اضافی زبان پیکز انسٹال کریں۔','Last 30 days'=>'پچھلے 30 دن','Last 7 days'=>'پچھلے 7 دن','Last generated: %s'=>'آخری پیداوار: %s','Lead paragraph (≤60 w)'=>'مقدمہ پیراگراف (≤60 الفاظ)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'ایک ماڈل فیلڈ کو خالی چھوڑیں تاکہ اس سطح کے لیے بلٹ ان ڈیفالٹ استعمال ہو۔ پلیس ہولڈر ٹیکسٹ دکھاتا ہے کہ کون سا ماڈل استعمال ہوگا۔','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'برانڈ کے نام اور زبان سے آزاد اصطلاحات کے لیے خالی چھوڑیں جنہیں کسی بھی زبان سے ترجمہ کرنے کے باوجود نافذ کیا جانا چاہیے۔','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'اس داخلہ کو تمام ہدف زبانوں پر لاگو کرنے کے لیے خالی چھوڑیں — برانڈ کے نام، مخففات، اور اصطلاحات کے لیے جو ہر ترجمہ میں حرف بہ حرف محفوظ رہنی چاہئیں۔','Leave blank to keep the existing key. Enter a new value to replace it.'=>'خالی چھوڑیں تاکہ موجودہ کلید کو برقرار رکھا جا سکے۔ اسے بدلنے کے لیے ایک نئی قیمت درج کریں۔','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'خالی چھوڑیں تاکہ بلٹ ان ڈیفالٹ استعمال کیا جا سکے۔ محفوظ شدہ اوور رائیڈ کو صاف کرنے سے اگلی بار ڈیفالٹ بحال ہو جائے گا۔','Legacy lf-social-share mu-plugin'=>'پرانا lf-social-share mu-پلاگ ان','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'پرانا lf-social-share mu-پلاگ ان کا پتہ چلا ہے۔ LF بنیادی OG سیٹ کو mu-پلاگ ان کے حوالے کر رہا ہے اور صرف og:locale + og:locale:alternate آؤٹ پٹ کر رہا ہے۔ آپ mu-پلاگ ان کو غیر فعال کر سکتے ہیں — LF کا بلٹ ان سوشل شیئر (SEO → سوشل شیئر ٹیب) اور اوپن گراف وہی فعالیت فراہم کرتے ہیں۔','Legal / Compliance'=>'قانونی / تعمیل','Legal / Compliance instructions'=>'قانونی / تعمیل ہدایات','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF ہمیشہ og:locale اور og:locale:alternate شامل کرتا ہے — وہ کثیر لسانی OG سگنلز جو کوئی بھی عمومی SEO پلگ ان صحیح طریقے سے پیدا نہیں کر سکتا۔ بنیادی OG سیٹ (og:title، og:description، og:image) کے لیے، LF اسے آؤٹ پٹ کرتا ہے جب کوئی اور پلگ ان موجود نہ ہو۔ جب کوئی SEO پلگ ان نصب ہو، تو LF بنیادی سیٹ کو چھوڑ دیتا ہے تاکہ نقل ٹیگز سے بچا جا سکے — یہ اس لیے نہیں کہ پلگ ان "بہتر" ہے، بلکہ نقل پیدا کرنا کوئی فائدہ نہیں دیتا۔','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF اپنی سائٹ میپ پیدا کرتا ہے جس میں تمام ترجمہ گروپوں کے لیے xhtml:link متبادل شامل ہیں۔ جب کوئی SEO پلگ ان نصب ہو، تو یہ ایک علیحدہ سائٹ میپ پیدا کرتا ہے — دونوں آزادانہ طور پر موجود ہیں۔ دونوں کو Google Search Console میں جمع کریں: SEO پلگ ان کا سائٹ میپ مواد کی دریافت کے لیے، LF کا سائٹ میپ زبان کے تعلقات کے سگنلز کے لیے۔','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'LF hreflang ٹیگز آؤٹ پٹ کر رہا ہے اور کثیر لسانی صفحات پر WordPress کے بنیادی canonical ٹیگ کو ہٹا دیا ہے۔','LF is suppressing hreflang output from: %s'=>'LF hreflang آؤٹ پٹ کو روک رہا ہے: %s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF ہر ترتیب شدہ زبان کے لیے درست hreflang آؤٹ پٹ کرتا ہے، بشمول x-default۔ عمومی SEO پلگ انز آپ کی LF روٹنگ کنفیگریشن تک رسائی نہیں رکھتے اور غلط URL مفروضوں کی بنیاد پر hreflang تیار کریں گے۔ LF ان کی آؤٹ پٹ کو فلٹر کے ذریعے دباتا ہے تاکہ تصادم سے بچا جا سکے۔','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF کثیر زبان JSON-LD آؤٹ پٹ کرتا ہے جس میں inLanguage تشریحات شامل ہیں جو اس کی زبان کی روٹنگ کنفیگریشن سے منسلک ہیں۔ جب ایک SEO پلگ ان انسٹال کیا جاتا ہے، تو LF اپنی اسکیمہ کو مکمل طور پر غیر فعال کر دیتا ہے: نقل JSON-LD گراف تصدیقی غلطیاں پیدا کرتے ہیں اور موجودہ گراف کو شامل کرنے کا کوئی صاف طریقہ نہیں ہے۔','LF provides'=>'LF فراہم کرتا ہے','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'LF کثیر زبان صفحات پر ورڈپریس کور canonical ٹیگ کو ہٹا دیتا ہے کیونکہ روٹر کی زبان-پیشگی ری رائٹ قواعد اور hreflang x-default صحیح canonical اشارے ہیں۔ یہ ایک دوہری canonical سے بچاؤ کرتا ہے اگر ایک SEO پلگ ان بھی ایک آؤٹ پٹ کرے۔ LF اپنی خود کی canonical شامل نہیں کرتا — زبان کی روٹنگ پہلے سے ہی ہر URL کو canonical بناتی ہے۔','Light'=>'ہلکا','Light (default — fast and cost-effective)'=>'ہلکا (پہلا — تیز اور کم قیمت)','Light (fast and cost-effective — Haiku / Flash)'=>'ہلکا (تیز اور کم قیمت — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'لائٹ: میٹا تفصیلات اور اقتباس پیدا کرنے کے لیے استعمال ہوتا ہے — تیز، کم قیمت۔','Limit results to pages in the given Lingua Forge language code.'=>'دی گئی لینگو فورج زبان کوڈ میں صفحات کے نتائج محدود کریں۔','Limits'=>'حدیں','Lingua Forge'=>'لینگوا فورج','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'لینگو فورج آپ کی ورڈپریس سائٹ میں کثیر زبان روٹنگ، AI سے چلنے والا ترجمہ، hreflang SEO ٹیگز، اور زبان سوئچر شامل کرتا ہے۔','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge مصنوعات کے صفحات پر WooCommerce مخصوص Open Graph خصوصیات شامل کرتا ہے تاکہ فیس بک، پنٹیرسٹ، اور دیگر پلیٹ فارمز پر مصنوعات کا URL شیئر کرنے سے صحیح مصنوعات کی قسم، قیمت، اور دستیابی ظاہر ہو۔','Lingua Forge AI Tools'=>'لینگوا فورج اے آئی ٹولز','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge ورڈپریس کور سوشل آئیکن بلاک کو متحرک شیئر URLs کے ساتھ بڑھاتا ہے۔ کسی بھی آئیکن کے لنک کو "share:" ویلیو پر سیٹ کریں اور LF اسے صحیح شیئر URL یا جاوا اسکرپٹ عمل میں ری رائٹ کرتا ہے — کوئی کسٹم کوڈ یا تھرڈ پارٹی پلگ ان کی ضرورت نہیں۔','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge ایک مخصوص XML سائٹ میپ بناتا ہے /lf-sitemap.xml پر جو آپ کے ترجمہ شدہ مواد کے لیے زبان کے متبادل روابط شامل کرتا ہے۔ یہ سائٹ میپ ورڈپریس کے بنیادی سائٹ میپ اور کسی بھی SEO پلگ ان کے سائٹ میپ کو مکمل کرتا ہے — اسے تبدیل نہیں کرتا۔','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge ایک مکمل کثیر زبان SEO حل ہے۔ کوئی اضافی SEO پلگ ان کی ضرورت نہیں۔','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge ایک مکمل کثیر زبان SEO حل ہے۔ کوئی اضافی SEO یا سائٹ میپ پلگ ان کی ضرورت نہیں۔','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'لینگوا فورج ہر زبان کے لیے ہر صفحہ پر <link rel="alternate" hreflang> ٹیگز پیدا کرتا ہے، بشمول x-default جو ماخذ زبان کی طرف اشارہ کرتا ہے۔ یہ گوگل اور دیگر سرچ انجنز کے لیے بنیادی کثیراللسانی SEO سگنل ہے — کوئی اضافی SEO پلگ ان درکار نہیں ہے۔','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge Open Graph اور Twitter Card میٹا ٹیگز آؤٹ پٹ کرتا ہے تاکہ شیئر شدہ URLs سوشل پلیٹ فارمز پر صحیح زبان، عنوان، تفصیل، اور تصویر ظاہر کریں۔','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge Schema.org JSON-LD ساختہ ڈیٹا آؤٹ پٹ کرتا ہے تاکہ سرچ انجن آپ کے مواد کی قسم، زبان، اور میٹا ڈیٹا کو سمجھ سکیں۔ یہ کثیر زبان مواد کے لیے inLanguage تشریحات کے لیے بنیادی طریقہ ہے تاکہ Google اور دیگر کرالرز کو معلومات فراہم کی جا سکے۔','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge دو Gutenberg خصوصیات کو محدود کرتا ہے تاکہ زبانوں کے درمیان اداریہ رویہ مستقل رہے۔ یہاں شامل ہوں جب آپ کو مکمل Gutenberg / FSE صلاحیتوں کی ضرورت ہو۔','Lingua Forge Settings'=>'لینگو فورج سیٹنگز','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'لینگو فورج دو آزاد کیشنگ پرتیں استعمال کرتا ہے تاکہ AI API کالز کو دہرانے سے بچا جا سکے۔ ہر ایک کو دیکھنے اور منظم کرنے کے لیے نیچے ٹیبز استعمال کریں۔','Lingua Forge uses two model tiers per provider:'=>'لینگو فورج ہر فراہم کنندہ کے لیے دو ماڈل سطحیں استعمال کرتا ہے:','Lingua Forge — Quick Translate'=>'لینگوا فورج — فوری ترجمہ','Lingua Forge — Settings'=>'لینگوا فورج — سیٹنگز','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Lingua Forge کے بلٹ ان سوشل شیئر اور Open Graph ماڈیولز وہ تمام فعالیت فراہم کرتے ہیں جو mu-plugin فراہم کرتا ہے، اور ساتھ ہی کثیر زبان og:locale سپورٹ بھی شامل ہے۔ آپ محفوظ طریقے سے mu-plugin کو غیر فعال کر سکتے ہیں۔','Link copied'=>'رابطہ کاپی کیا گیا','link(s)'=>'لنک','Links'=>'لنکس','Load available languages'=>'دستیاب زبانیں لوڈ کریں','Load content'=>'مواد لوڈ کریں','Loaded from cache.'=>'کیش سے لوڈ کیا گیا۔','Loading…'=>'لوڈ ہو رہا ہے…','Locale only'=>'صرف لوکل','Locked — a conflicting SEO plugin is active. See the notice above.'=>'مغلوب — ایک متصادم SEO پلگ ان فعال ہے۔ اوپر نوٹس دیکھیں۔','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'لوکو ترجمہ اپنی مرضی کے ترجمے wp-content/languages/loco/ میں محفوظ کرتا ہے — ایک جگہ جو کہ ایک WP کور اپ ڈیٹ، پلگ ان کی دوبارہ تنصیب، یا اگر لوکو ترجمہ خود کو ہٹا دیا جائے تو خاموشی سے مٹ سکتی ہے۔ یہاں فائلیں کاپی کرنے سے وہ Lingua Forge i18n-overrides ڈائریکٹری میں منتقل ہو جاتی ہیں، جو ان تمام واقعات کے دوران برقرار رہتی ہے اور ہر درخواست پر خود بخود لوڈ ہوتی ہے۔','Loco Translate — Copy to Safe Storage'=>'لوکو ترجمہ — محفوظ اسٹوریج پر کاپی کریں','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'سب سے کم ورڈپریس صلاحیت جو AI خصوصیات کو فعال کرنے کی اجازت دیتی ہے۔ اس کو سخت کرنا ملٹی-مصنف سائٹس پر شریک کار یا آزمائشی اکاؤنٹس کو ادائیگی شدہ AI کالز چلانے سے روکتا ہے۔ فیچر کے مطابق override کریں via the linguaforge_required_capability فلٹر۔','Maintenance'=>'مرمت','Maintenance Tab'=>'مینٹیننس ٹیب','Make casual'=>'غیر رسمی بنائیں','Make concise'=>'مختصر بنائیں','Make formal'=>'رسمی بنائیں','Mark citations needed'=>'حوالہ جات کی ضرورت کو نشان زد کریں','Max context characters'=>'مکمل سیاق و سباق کے کردار زیادہ سے زیادہ','Max hints characters'=>'اشارہ کے کردار زیادہ سے زیادہ','Max input characters'=>'زیادہ سے زیادہ ان پٹ حروف','Max output tokens'=>'زیادہ سے زیادہ آؤٹ پٹ ٹوکن','Maximum characters accepted from the input field. Default: 8 000.'=>'ان پٹ فیلڈ سے قبول شدہ زیادہ سے زیادہ کردار۔ ڈیفالٹ: 8،000۔','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'جب کوئی اشارہ فراہم نہیں کیا جاتا تو ای اے آئی کو پاس کیے گئے موجودہ پوسٹ مواد کے زیادہ سے زیادہ کردار۔ ڈیفالٹ: 6،000۔','Maximum characters read from the Hints field. Default: 2 000.'=>'اشاروں کے میدان سے پڑھنے کے لیے زیادہ سے زیادہ کردار۔ ڈیفالٹ: 2،000۔','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'ای اے آئی کو بھیجے گئے پوسٹ مواد کی زیادہ سے زیادہ تعداد۔ 0 کا مطلب کوئی حد نہیں — مکمل مواد ہمیشہ بھیجا جاتا ہے (تجویز کردہ)۔ ایک غیر صفر قیمت مقرر کریں صرف اگر آپ کے فراہم کنندہ کے پاس سخت سیاق و سباق کی ونڈو ہے۔ جب مواد کاٹ دیا جاتا ہے تو PHP ایرر لاگ میں ایک وارننگ لکھی جاتی ہے۔','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'ایک ترجمہ جواب میں AI زیادہ سے زیادہ ٹوکن پیدا کر سکتا ہے۔ اگر ترجمہ خاموشی سے ختم ہو رہا ہے، تو اس قدر کو بڑھائیں۔ ڈیفالٹ: 16,000۔','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'ای اے آئی ہر پیداوار رن پر زیادہ سے زیادہ ٹوکن پیدا کر سکتا ہے۔ اگر مکمل مضامین کاٹ رہے ہیں تو اسے بڑھائیں۔ ڈیفالٹ: 8،192۔','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'ای اے آئی ہر جلدی ترجمہ پر زیادہ سے زیادہ ٹوکن پیدا کر سکتا ہے۔ ڈیفالٹ: 2،000۔','Meta Description'=>'میٹا تفصیل','Meta description'=>'میٹا تفصیل','Meta Description, Excerpt Generator'=>'میٹا تفصیل، اقتباس جنریٹر','Metric'=>'میٹرک','Minimum role'=>'کم از کم کردار','Missing pattern name or language.'=>'پٹرن کا نام یا زبان غائب ہے۔','Mode'=>'طریقہ','Model'=>'ماڈل','Model tier'=>'ماڈل سطح','Models'=>'ماڈلز','Models Tab (General)'=>'ماڈلز ٹیب (عام)} ,{','Modified'=>'تبدیل شدہ','Most recent cached block'=>'سب سے حالیہ کیش شدہ بلاک','Most recent cached response'=>'سب سے حالیہ کیش شدہ جواب','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'ملٹی لسانی روٹنگ، مکمل ملٹی لسانی SEO (hreflang، Open Graph، Schema.org، سائٹ میپ)، اور WordPress کے لیے AI مواد کے اوزار۔ زبان کا پتہ لگانا، URL روٹنگ، ترجمہ، مواد کی تخلیق، اور ایک مکمل SEO پرت — کوئی ساتھی پلگ ان کی ضرورت نہیں۔','Name displayed in this language. Leave empty to use the source name.'=>'اس زبان میں دکھایا گیا نام۔ خالی چھوڑیں تاکہ ماخذ کا نام استعمال ہو۔','Navigation'=>'نیویگیشن','Navigation has no content to translate.'=>'نیویگیشن کا کوئی مواد ترجمہ کے لیے موجود نہیں۔','Navigation not found.'=>'نیویگیشن نہیں ملی۔','Navigation posts are translated via the Router tab, not this button.'=>'نیویگیشن پوسٹس راؤٹر ٹیب کے ذریعے ترجمہ کی جاتی ہیں، اس بٹن کے ذریعے نہیں۔','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'نیویگیشن ترجمہ کے لیے ایک فعال AI فراہم کنندہ کی ضرورت ہے۔ API کیز ٹیب میں ایک API کلید ترتیب دیں۔','Navigations'=>'نیویگیشنز','Network error — could not reach the WordPress AJAX endpoint.'=>'نیٹ ورک کی خرابی — ورڈپریس AJAX اینڈپوائنٹ سے رسائی حاصل نہیں ہو سکی۔','No %s version found in this translation group.'=>'اس ترجمہ گروپ میں کوئی %s ورژن نہیں ملا۔','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'کوئی کارروائی کی ضرورت نہیں۔ گوگل نے جنوری 2024 میں اپنی سائٹ میپ پنگ اینڈپوائنٹ کو ختم کر دیا ہے اور اب یہ robots.txt Sitemap: ہدایت کے ذریعے سائٹ میپ کو دریافت کرتا ہے — جسے LF پہلے سے کنفیگر کر چکا ہے۔ گوگل اسے اپنی اگلی کرال پر اٹھائے گا۔','No AI provider configured.'=>'AI فراہم کنندہ ترتیب نہیں دیا گیا۔','No AI provider configured. Add an API key in Settings → API Keys.'=>'کوئی AI فراہم کنندہ کنفیگر نہیں ہے۔ سیٹنگز → API کیز میں API کلید شامل کریں۔','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'منتخب ونڈو (%s) میں AI استعمال کا ریکارڈ نہیں ہے۔ اوپر ایک وسیع رینج منتخب کریں۔','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'ابھی تک AI استعمال کا ریکارڈ نہیں ہے۔ جب بھی کوئی ایڈیٹر ترجمہ کرتا ہے، میٹا تفصیل تیار کرتا ہے، یا کوئی اور AI خصوصیت استعمال کرتا ہے، تو کل یہاں ظاہر ہوں گے۔','No API key configured for this provider.'=>'اس فراہم کنندہ کے لیے کوئی API کلید ترتیب نہیں دی گئی۔','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'کوئی بلٹ ان ہدایات نہیں — ہر AI فیچر اپنی مخصوص ڈیفالٹس استعمال کرتا ہے۔ اپنی سائٹ کے قواعد شامل کرنے کے لیے نیچے دیے گئے کسٹم پرامپٹ ہدایات کے فیلڈ کو پُر کریں۔','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'کوئی متصادم SEO پلگ ان کا پتہ نہیں چلا۔ Lingua Forge تمام SEO آؤٹ پٹ کو خود مختار طریقے سے ہینڈل کر رہا ہے۔','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'ابھی تک کوئی کسٹم لوکو ترجمہ فائلیں نہیں ملی ہیں۔ یہ یہاں ظاہر ہوتی ہیں جب آپ لوکو ترجمہ میں ترجمہ محفوظ کرتے ہیں۔','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'کوئی خارجی OG پلگ ان کا پتہ نہیں چلا۔ LF مکمل OG + Twitter Card سیٹ آؤٹ پٹ کر رہا ہے۔','No file was selected.'=>'کوئی فائل منتخب نہیں کی گئی۔','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'موجودہ فلٹر سے کوئی مفہومیہ داخلہ مطابقت نہیں رکھتا۔ تمام داخلوں کو دیکھنے کے لیے فلٹر صاف کریں، یا نیچے ایک نیا داخلہ شامل کریں۔','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'ابھی تک کوئی مفہومیہ داخلہ نہیں ہے۔ ترجمہ میں اصطلاحات کے نفاذ کے لیے نیچے ایک شامل کریں۔','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'کوئی H1 نہیں ملا۔ عموماً پوسٹ کا عنوان H1 ہوتا ہے — اپنی تھیم کو چیک کریں کہ یہ اسے آؤٹ پٹ کر رہا ہے۔','No images found in content.'=>'مواد میں کوئی تصاویر نہیں ملتیں۔','No internal links found to update.'=>'اپ ڈیٹ کرنے کے لیے کوئی داخلی روابط نہیں ملے۔','No language-specific template parts found to map.'=>'زبان سے مخصوص سانچہ کے حصے نہیں ملے۔','No LF meta description set — using excerpt/content.'=>'LF میٹا تفصیل سیٹ نہیں — اقتباس/مواد استعمال کیا جا رہا ہے۔','No links found.'=>'کوئی لنک نہیں ملا۔','No links found. Internal links improve crawlability and user navigation.'=>'کوئی روابط نہیں ملے۔ داخلی روابط کرال کرنے اور صارف کی نیویگیشن کو بہتر بناتے ہیں۔','No meta description found. Generate one via the AI meta description feature.'=>'کوئی میٹا تفصیل نہیں ملی۔ AI میٹا تفصیل فیچر کے ذریعے ایک تیار کریں۔','No navigation references needed updating.'=>'نیویگیشن کے حوالے کی ضرورت نہیں۔','No override files uploaded yet.'=>'ابھی تک کوئی اوور رائڈ فائل اپ لوڈ نہیں کی گئی۔','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'کوئی فزیکل robots.txt فائل نہیں ملی۔ ورڈپریس اسے ورچوئلی پیدا کر رہا ہے اور LF کا سائٹ میپ ہدایت خود بخود شامل ہے۔','No published posts found for the selected filters.'=>'منتخب فلٹرز کے لیے کوئی شائع شدہ پوسٹس نہیں ملتیں۔','No response from AI provider. Check your API key and try again.'=>'AI فراہم کنندہ سے کوئی جواب نہیں۔ اپنی API کلید چیک کریں اور دوبارہ کوشش کریں۔','No response from provider — check the error log for details.'=>'پرووائیڈر سے جواب موصول نہیں ہوا — تفصیلات کے لیے ایرر لاگ چیک کریں۔','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'کوئی ثانوی زبانیں ترتیب نہیں دی گئی ہیں۔ اوپر ایک زبان پیک انسٹال کریں تاکہ ٹیمپلیٹ اسکیفولڈنگ فعال ہو سکے۔','No source content found to translate.'=>'کوئی ماخذ مواد ترجمہ کے لیے نہیں ملا۔','No source page linked yet.'=>'ابھی تک کوئی ماخذ صفحہ منسلک نہیں ہے۔','No template part references needed updating.'=>'سانچہ کے حصے کے حوالے کی ضرورت نہیں۔','No title set.'=>'کوئی عنوان مقرر نہیں۔','No translated content found. The sitemap will populate once posts have been translated.'=>'کوئی ترجمہ شدہ مواد نہیں ملا۔ ایک بار پوسٹس کا ترجمہ ہو جائے، سائٹ میپ بھر جائے گا۔','No translation found — analyzed the source language version.'=>'کوئی ترجمہ نہیں ملا — ماخذ زبان کا ورژن تجزیہ کیا گیا۔','No {lang} translation registered (TRID missing)'=>'کوئی {lang} ترجمہ رجسٹرڈ نہیں ہے (TRID غائب ہے)','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'ابھی تیار نہیں۔ سائٹ میپ پہلی بار سائٹ میپ URL پر جانے کے بعد تیار ہوتا ہے اور 24 گھنٹے کے لیے کیش ہو جاتا ہے۔','Notes'=>'نوٹس','Nothing — all types disabled'=>'کچھ بھی نہیں — تمام اقسام غیر فعال ہیں۔','Notice message'=>'نوٹس پیغام','Notice settings'=>'نوٹس سیٹنگز','Notify search engines'=>'تلاش انجنز کو اطلاع دیں۔','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'OG/Twitter Card ٹیگز: LF کے Open Graph ماڈیول (SEO → Open Graph & Twitter Cards) کے ذریعے ہینڈل کیا جاتا ہے۔','Oldest cached block'=>'سب سے پرانا کیش شدہ بلاک','Oldest cached response'=>'سب سے پرانا کیش شدہ جواب','Only .mo files are accepted.'=>'صرف .mo فائلیں قبول کی جاتی ہیں۔','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'اوپن گراف اور ٹویٹر کارڈز','Open Graph output'=>'Open Graph آؤٹ پٹ','Open Graph settings saved.'=>'Open Graph سیٹنگز محفوظ ہو گئی ہیں۔','Open Search Console →'=>'Open Search Console →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'براؤزر کے مقامی ویب شیئر شیٹ (iOS، Android، کچھ ڈیسک ٹاپس) کو کھولیں۔ اگر سپورٹ نہیں کرتا تو کلپ بورڈ کاپی پر واپس آتا ہے۔','OpenAI (GPT)'=>'اوپن اے آئی (جی پی ٹی)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'ایڈیٹرز کے لیے اختیاری سیاق و سباق (مثلاً "ASIC = ایپلیکیشن-خصوصی انٹیگریٹڈ سرکٹ؛ تکنیکی سیاق و سباق میں انگریزی میں محفوظ رکھیں").','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'اختیاری۔ Bing پہلے ہی robots.txt سے Sitemap: ہدایت پڑھتا ہے — یہ صرف ایک فوری دوبارہ کرال کو متحرک کرتا ہے، اگلی شیڈول شدہ چیک کا انتظار کیے بغیر۔','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'اختیاری۔ Yandex پہلے ہی robots.txt سے Sitemap: ہدایت پڑھتا ہے — یہ صرف ایک فوری دوبارہ کرال کو متحرک کرتا ہے، اگلی شیڈول شدہ چیک کا انتظار کیے بغیر۔','Output'=>'نتیجہ','Output Article or WebPage schema on singular posts and pages'=>'سنگل پوسٹس اور صفحات پر آرٹیکل یا ویب پیج اسکیمہ آؤٹ پٹ کریں۔','Output hreflang tags in wp_head'=>'wp_head میں hreflang ٹیگز آؤٹ پٹ کریں۔','Output mode'=>'آؤٹ پٹ موڈ','Output Open Graph tags in wp_head'=>'wp_head میں Open Graph ٹیگز آؤٹ پٹ کریں۔','Output Product schema on WooCommerce product pages'=>'WooCommerce مصنوعات کے صفحات پر پروڈکٹ اسکیمہ آؤٹ پٹ کریں۔','Output Schema.org JSON-LD in wp_head'=>'آؤٹ پٹ Schema.org JSON-LD in wp_head','Output tokens'=>'آؤٹ پٹ ٹوکنز','Output WebSite schema on the front page and blog index'=>'ہوم پیج اور بلاگ انڈیکس پر ویب سائٹ اسکیمہ آؤٹ پٹ کریں','Overall SEO score'=>'مجموعی SEO اسکور','overridden'=>'اوور رائیڈ کیا گیا','Override file deleted.'=>'اوور رائڈ فائل حذف کر دی گئی۔','Override file uploaded successfully.'=>'اوور رائڈ فائل کامیابی سے اپ لوڈ ہوئی۔','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'اس صفحہ پر ترجمہ اور مواد کی تخلیق کے لیے AI پری سیٹ کو اووررائیڈ کرتا ہے۔ دیگر تمام خصوصیات ہمیشہ عالمی پری سیٹ استعمال کرتی ہیں۔','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'اس صفحہ پر ترجمہ اور مواد کی تخلیق کے لیے AI پری سیٹ کو اووررائیڈ کرتا ہے۔ سائٹ بھر میں حسبِ ضرورت پرامپٹ ہدایات (سیٹنگز → رویہ) ہر درخواست کے ساتھ شامل کی جاتی ہیں، چاہے اس انتخاب سے کوئی فرق نہ پڑے۔','Overview'=>'جائزہ','Page'=>'صفحہ','Part'=>'پارٹ','Paste a footnote, sentence, or any snippet here…'=>'یہاں ایک نوٹ، جملہ، یا کوئی بھی ٹکڑا چسپاں کریں…','Paste text, or select text in the editor first…'=>'متن چسپاں کریں، یا پہلے ایڈیٹر میں متن منتخب کریں…','Paste text, or select text on the page first…'=>'متن چسپاں کریں، یا پہلے صفحہ پر متن منتخب کریں…','Paste your API key…'=>'اپنی API کلید چسپاں کریں…','Path prefix — example.com/de/'=>'پاتھ پری فکس — example.com/de/','Pattern'=>'پیٹرن','Pattern has no content to translate.'=>'پٹرن کا مواد ترجمہ کے لیے نہیں ہے۔','Pattern not found.'=>'پٹرن نہیں ملا۔','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'پٹرن ترجمہ کیا گیا اور محفوظ کیا گیا۔ مواد کو اپنے CPT پوسٹ میں کاپی کریں یا اسے ری یوز ایبل بلاک کے لیے شروع کرنے کے طور پر استعمال کریں۔','Pattern translation failed.'=>'پیٹرن کا ترجمہ ناکام رہا۔','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes.'=>'پوسٹ کے حساب سے کیش AI سے تیار شدہ ترجمے، میٹا تفصیلات، اقتباسات، اور مواد کے لیے۔ ہمیشہ فعال — کوئی علیحدہ ٹوگل کی ضرورت نہیں۔ جب مواد یا AI فراہم کنندہ/ماڈل تبدیل ہوتا ہے تو اندراجات خود بخود منسوخ ہو جاتے ہیں۔','Permalink rules flushed successfully.'=>'پرم لنک قواعد کامیابی سے فلش ہو گئے۔','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'ہمیشہ کے لیے اس زبان سے منسلک تمام ٹیمپلیٹس، ٹیمپلیٹ پارٹس، پیٹرن، نیویگیشن مینو، پوسٹس، صفحات، کسٹم پوسٹ ٹائپ، مصنوعات، اور مصنوعات کی قسمیں حذف کر دیتا ہے۔ اس کے علاوہ، ورڈپریس لوکل پیک فائلیں بھی ہٹا دیتا ہے تاکہ یہ زبان اب روٹر میں ظاہر نہ ہو۔ یہ عمل واپس نہیں لیا جا سکتا۔','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'کیا آپ %s کو مستقل طور پر ان انسٹال کرنا چاہتے ہیں؟ یہ اس زبان کے لیے تمام ترجمہ شدہ مواد کو حذف کر دے گا اور واپس نہیں لیا جا سکتا۔','Permission denied.'=>'اجازت نامہ مسترد۔','Persuasive'=>'قائل','PHP constant'=>'PHP مستقل','Pin on Pinterest'=>'پینٹیرسٹ پر پن کریں','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'اصطلاحات کو پن کریں جن کا ترجمہ نہیں ہونا چاہیے یا جنہیں مخصوص طریقے سے پیش کرنا چاہیے (مثلاً برانڈ نام، مصنوعات کے نام، مخفف)۔ گلاسری پابندیاں ہر AI ترجمہ درخواست میں شامل کی جاتی ہیں: پوسٹ ترجمہ، میٹا تفصیل، اقتباس، اور FSE ٹیمپلیٹ ترجمہ۔','Ping Bing'=>'بنگ کو پنگ کریں','Ping Yandex'=>'یاندیکس کو پنگ کریں','Plain language'=>'سادہ زبان','Please enter some instructions first…'=>'براہ کرم پہلے کچھ ہدایات درج کریں…','Please enter some text first…'=>'براہ کرم پہلے کچھ متن درج کریں…','Plugin'=>'پلگ ان','Post'=>'پوسٹ','Post not found or not published.'=>'پوسٹ نہیں ملی یا شائع نہیں ہوئی۔','Post not found.'=>'پوسٹ نہیں ملی۔','Post on X / Twitter'=>'X / ٹویٹر پر پوسٹ کریں','Post Types'=>'پوسٹ ٹائپز','Prefilled from excerpt. Edit to override.'=>'خلاصہ سے پہلے سے بھرا ہوا۔ اوور رائیڈ کرنے کے لیے ترمیم کریں۔','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'قیمت اور دستیابی ہمیشہ ماخذ زبان کی مصنوعات کی عکاسی کرتی ہے (مشترکہ اسٹاک ماڈل)۔ ٹیگز صرف اس وقت آؤٹ پٹ ہوتے ہیں جب LF کا اوپن گراف ماڈیول "مکمل" یا "خودکار" موڈ پر سیٹ ہو اور کوئی متصادم SEO پلگ ان موجود نہ ہو۔','Primary Language'=>'پہلی زبان','Primary language'=>'پہلی زبان','Primary language saved.'=>'پہلی زبان محفوظ کی گئی۔','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'اصلی زبان: وہ زبان جس میں آپ کا موجودہ مواد لکھا گیا ہے۔ تمام ترجمے اسی زبان سے تیار کیے جاتے ہیں؛ اسے تبدیل کرنے سے کوئی پوسٹ منتقل یا حذف نہیں ہوتی۔','Processing…'=>'پروسیس ہو رہا ہے…','Product'=>'مصنوعات','Product / eCommerce'=>'مصنوعات / ای کامرس','Product Open Graph'=>'مصنوعات کا اوپن گراف','Product — WooCommerce product pages'=>'مصنوعات — ووکامرس مصنوعات صفحات','Profile'=>'پروفائل','Provider'=>'فراہم کنندہ','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'فراہم کنندہ نے کوئی متن واپس نہیں کیا۔ تفصیلی ناکامی کی وجہ کے لیے ورڈپریس کی غلطی لاگ چیک کریں۔','Quality'=>'معیار','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'معیار (ڈیفالٹ — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'معیار (سونٹ / GPT-4o / جیمینی پرو)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'معیار: پوسٹ ترجمہ اور مواد پیدا کرنے کے لیے استعمال ہوتا ہے — اعلیٰ معیار، زیادہ قیمت۔','Quick Translate'=>'جلدی ترجمہ','Quick Translation'=>'جلدی ترجمہ','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'جلدی ترجمہ کو اسنپٹ/چنک موڈ کے لیے استعمال کیا جاتا ہے — شارٹ پیغامات کو ٹول بار، ایڈیٹر، یا بلاک پاپ اوور سے مطالبہ پر ترجمہ کیا جاتا ہے۔ یہ مکمل صفحہ ترجمہ سے ایک علیحدہ، ہلکی سی ترتیب استعمال کرتا ہے تاکہ جواب تیز اور کم قیمت رہیں۔','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Gutenberg\'s canLockBlocks کو دوبارہ فعال کرتا ہے۔ یہ اداریہ ٹیمپلیٹس کے لیے مفید ہے جنہیں مخصوص بلاکس کو حرکت دینے یا حذف کرنے سے روکنا ہوتا ہے۔','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'supportsTemplateMode کو دوبارہ فعال کرتا ہے۔ یہ مکمل سائٹ ایڈیٹنگ ورک فلو کے لیے بنیادی ہے جہاں پوسٹ سطح کے ٹیمپلیٹ اوور رائیڈز ارادتا ہوتے ہیں۔','Re-generates and updates the cached result.'=>'کیش شدہ نتیجہ کو دوبارہ پیدا اور اپ ڈیٹ کرتا ہے۔','Re-scan'=>'دوبارہ اسکین کریں','Re-scanning…'=>'دوبارہ اسکین کر رہے ہیں…','Re-translate'=>'دوبارہ ترجمہ کریں','Reading time'=>'پڑھنے کا وقت','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'براؤزر کے Accept-Language ہیڈر کی بنیاد پر زائرین کو ان کی ترجیحی زبان پر ری ڈائریکٹ کریں','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'مزید بہتر بنائیں — مثلاً "اسے مختصر کریں" یا "رسمی انداز استعمال کریں"…','Refine further:'=>'مزید بہتر بنائیں:','Refinement'=>'ترقی','Refinement failed — please try again.'=>'ترقی میں ناکامی — براہ کرم دوبارہ کوشش کریں۔','Refining…'=>'ترقی پذیر…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'ورڈپریس کے ری رائٹ قواعد کو دوبارہ پیدا کرتا ہے تاکہ URL پری فکسز، زبان مخصوص سلگ، اور آرکائیو ری رائٹس سب ہم آہنگ ہوں۔ بنیادی زبان تبدیل کرنے یا نئی زبان کی حمایت شامل کرنے کے بعد ضروری ہے۔','Remove stored key'=>'محفوظ شدہ کلید کو ہٹائیں','Report an issue on GitHub'=>'گٹ ہب پر مسئلہ رپورٹ کریں','Request failed — please try again.'=>'درخواست ناکام — براہ کرم دوبارہ کوشش کریں۔','Request failed.'=>'درخواست ناکام۔','Request failed. Check your connection.'=>'درخواست ناکام۔ اپنی کنکشن چیک کریں۔','Request failed. Please try again.'=>'درخواست ناکام۔ براہ کرم دوبارہ کوشش کریں۔','Requests'=>'درخواستیں','Reset'=>'ری سیٹ','Result will appear here…'=>'نتیجہ یہاں ظاہر ہوگا…','Retranslate'=>'دوبارہ ترجمہ کریں','Retranslating…'=>'دوبارہ ترجمہ ہو رہا ہے…','Review carefully — links and slugs not updated.'=>'احتیاط سے جائزہ لیں — روابط اور سلگ اپ ڈیٹ نہیں ہوئے۔','Review translation before applying'=>'درخواست سے پہلے ترجمہ کا جائزہ لیں','Revise'=>'دوبارہ جائزہ لیں','Revision'=>'نظر ثانی','Revision Type'=>'نظر ثانی کی قسم','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt کو سائٹ میپ ہدایت کے ساتھ اپ ڈیٹ کیا گیا۔','Router'=>'روٹر','Router Tab'=>'روٹر ٹیب','Run AI Analysis'=>'AI تجزیہ چلائیں','Save analysis settings'=>'تجزیہ کی ترتیبات محفوظ کریں','Save Debug Setting'=>'ڈیبگ سیٹنگ محفوظ کریں','Save Hreflang Settings'=>'ہریف لینگ سیٹنگز محفوظ کریں','Save Open Graph Settings'=>'اوپن گراف سیٹنگز محفوظ کریں','Save Router Settings'=>'روٹر سیٹنگز محفوظ کریں','Save Schema.org Settings'=>'Schema.org سیٹنگز محفوظ کریں','Save Settings'=>'سیٹنگز محفوظ کریں','Save Sitemap Settings'=>'سائٹ میپ سیٹنگز محفوظ کریں','Save Social Share Settings'=>'سوشل شیئر سیٹنگز محفوظ کریں','Save the post to persist changes.'=>'تبدیلیاں محفوظ کرنے کے لیے پوسٹ کو محفوظ کریں۔','Save Uninstall Setting'=>'ان انسٹال سیٹنگ محفوظ کریں','Save WooCommerce SEO Settings'=>'ووکامرس SEO سیٹنگز محفوظ کریں','Saved to the meta description field when you apply.'=>'جب آپ درخواست دیں گے تو یہ فیلڈ میں محفوظ ہو جائے گا۔','Scan failed: '=>'اسکین ناکام: ','Scan request failed. Please try again.'=>'اسکین کی درخواست ناکام ہو گئی۔ براہ کرم دوبارہ کوشش کریں۔','Scanning posts for broken language links…'=>'ٹوٹے ہوئے زبان کے لنکس کے لیے پوسٹس اسکین کر رہے ہیں…','Schema output deferred.'=>'Schema آؤٹ پٹ مؤخر کر دیا گیا۔','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'Schema.org JSON-LD','Schema.org output'=>'Schema.org آؤٹ پٹ','Schema.org settings saved.'=>'Schema.org سیٹنگز محفوظ کی گئی ہیں۔','Search'=>'تلاش','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'سرچ کنسول انڈیکسنگ اور کوریج کی غلطیوں کی نگرانی کے لیے مفید ہے، لیکن دریافت کے لیے ضروری نہیں ہے۔','Search Results'=>'تلاش کے نتائج','Security check failed — file path is not permitted.'=>'سیکیورٹی چیک ناکام — فائل کا راستہ اجازت یافتہ نہیں ہے۔','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'اس زبان کا انتخاب کریں تاکہ اس کے FSE ٹیمپلیٹس، ٹیمپلیٹ پارٹس، اور نیویگیشن مینو کو منظم کیا جا سکے۔','Select language'=>'زبان منتخب کریں','Send via Telegram'=>'ٹیلیگرام کے ذریعے بھیجیں','Send via WhatsApp'=>'واٹس ایپ کے ذریعے بھیجیں','SEO'=>'SEO','SEO Analysis'=>'SEO تجزیہ','SEO character-count info'=>'SEO حروف کی گنتی کی معلومات','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'SEO پلگ ان کا پتہ چلا: %s۔ LF صرف og:locale اور og:locale:alternate آؤٹ پٹ کر رہا ہے؛ معلوم شدہ پلگ ان مکمل OG سیٹ کو ہینڈل کرتا ہے۔','SEO plugins and conflict avoidance:'=>'SEO پلگ انز اور تنازعہ سے بچاؤ:','SEO Tab'=>'SEO ٹیب','Server setup (subdomain)'=>'سرور سیٹ اپ (سب ڈومین)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'یہ سائٹ بھر میں تمام خصوصیات کے لیے ڈیفالٹ AI رویہ مقرر کرتا ہے۔ انفرادی پوسٹس اس کو ترجمانی اور مواد تخلیق کے لیے اوور رائیڈ کر سکتی ہیں، جو کہ Lingua Forge میٹا باکس کے ذریعے ہے۔','Settings'=>'سیٹنگز','Settings saved.'=>'سیٹنگز محفوظ ہو گئی ہیں۔','Share on Facebook'=>'فیس بک پر شیئر کریں','Share on LinkedIn'=>'لنکڈ ان پر شیئر کریں','Share on Mastodon'=>'ماسٹودون پر شیئر کریں','Share via email (mailto:)'=>'ای میل کے ذریعے شیئر کریں (mailto:)','Show home link'=>'ہوم لنک دکھائیں','Shown when no translation exists for the visitor\'s language.'=>'جب کوئی ترجمہ موجود نہ ہو تو ظاہر ہوتا ہے۔','Single'=>'سنگل','Single %s'=>'سنگل %s','Single: %s'=>'سنگل: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'UTC دن کے لیے سائٹ بھر میں AI درخواستوں کی چھت (یہ دونوں ٹولبار ترجمے اور بلاک ترمیمات کو شمار کرتا ہے)۔ کاؤنٹر UTC آدھی رات کو ری سیٹ ہوتا ہے۔ اسے 0 پر سیٹ کریں تاکہ حد کو غیر فعال کیا جا سکے۔','Sitemap'=>'سائٹ میپ','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'سائٹ میپ کیشے فلش کر دی گئی ہے۔ یہ اگلی بار سائٹ میپ URL پر جانے پر دوبارہ تیار کی جائے گی۔','Sitemap output'=>'سائٹ میپ آؤٹ پٹ','Sitemap settings saved.'=>'سائٹ میپ سیٹنگز محفوظ کی گئی ہیں۔','Sitemap URL'=>'سائٹ میپ URL','Size'=>'سائز','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'سوشل آئیکون بلاک شیئر: URLs: LF کے بلٹ ان سوشل شیئر (SEO → Social Share) کے ذریعے ہینڈل کیا گیا ہے۔','Social Share'=>'سوشل شیئر','Social Share settings saved.'=>'سوشل شیئر سیٹنگز محفوظ ہوگئیں۔','Some link fixes failed.'=>'کچھ روابط کی درستگی ناکام رہی۔','Some nav ref fixes failed.'=>'کچھ نیویگیشن ریفرنسز کی درستگی ناکام رہی۔','Some part fixes failed.'=>'کچھ حصوں کی درستگی ناکام رہی۔','Some parts could not be created.'=>'کچھ حصے نہیں بن سکے۔','Some templates could not be created.'=>'کچھ ٹیمپلیٹس نہیں بن سکے۔','Some translations failed.'=>'کچھ ترجمے ناکام رہے۔','source'=>'ماخذ','Source file not found.'=>'ماخذ فائل نہیں ملی۔','Source lang'=>'ماخذ زبان','Source language'=>'ماخذ زبان','Source term'=>'ماخذ اصطلاح','Standard'=>'معیاری','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'معیاری ہر خصوصیت کے اپنے مخصوص درجہ حرارت کا استعمال کرتا ہے: ترجمہ T=0.2 (مستحکم)، فوری ترجمہ T=0.4، مواد تخلیق T=0.6 (تخلیقی)۔ دیگر پری سیٹس تمام خصوصیات پر ایک مقررہ درجہ حرارت لاگو کرتی ہیں۔','Status'=>'حالت','Status / Actions'=>'حالت / عمل','Storytelling'=>'کہانی سنانا','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'قانونی، ریگولیٹری، طبی، یا تکنیکی مواد کے لیے سخت تحفظ کا موڈ۔ جب فعال ہو، ہر AI خصوصیت کم سیمپلنگ درجہ حرارت استعمال کرتی ہے اور اپنے نظام پرامپٹ کے نیچے اضافی متن شامل کرتی ہے — اصطلاحات، آرٹیکل نمبرز، یونٹس، برانڈ نام، اور ریگولیٹری زبان کو حرف بہ حرف محفوظ رکھا جاتا ہے، نہ کہ پیرا فریز کیا جاتا ہے۔','Structured Outline'=>'ساختی خاکہ','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'ذیلی ڈومین موڈ آپ کے ویب سرور کو تمام زبان کے ذیلی ڈومینز (مثلاً de.example.com) کو اس ورڈپریس تنصیب کی طرف اشارہ کرنے کی ضرورت ہے۔ موڈ تبدیل کرنے کے بعد، permalink قواعد کو فلش کریں اور کسی بھی کیش کو صاف کریں۔ اگر آپ کا ہوم یو آر ایل www شامل ہے (مثلاً www.example.com)، تو lf_base_domain فلٹر کا استعمال کریں تاکہ صرف بنیادی ڈومین سیٹ کیا جا سکے تاکہ ذیلی ڈومینز صحیح طریقے سے بنیں۔','Subdomain — de.example.com/'=>'ذیلی ڈومین — de.example.com/','Submit this URL to Google Search Console alongside your main sitemap.'=>'اس URL کو گوگل سرچ کنسول میں اپنی مرکزی سائٹ میپ کے ساتھ جمع کروائیں۔','Submit to Reddit'=>'ریڈٹ پر جمع کروائیں','Suggested meta description'=>'تجویز کردہ میٹا تفصیل','Suggested title'=>'تجویز کردہ عنوان','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'موجودہ فراہم کنندگان: انتھروپک (کلود), اوپن اے آئی (GPT), گوگل (جمینی)۔ صرف ایک فراہم کنندہ فعال ہوتا ہے۔ فعال فراہم کنندہ کو جنرل ٹیب پر منتخب کریں۔','Suppressed: %s.'=>'مضبوط: %s۔','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6، فی خصوصیت','Tag'=>'ٹیگ','Tags emitted'=>'نکالے گئے ٹیگز','Target lang'=>'ہدف زبان','Target Language'=>'ہدف زبان','Target language'=>'ہدف زبان','Target term'=>'ہدف اصطلاح','Target: 140–160 chars for optimal SERP display'=>'ہدف: 140–160 حروف مثالی SERP نمائش کے لیے','Technical'=>'تکنیکی','Technical / Scientific'=>'تکنیکی / سائنسی','Technical / Scientific instructions'=>'تکنیکی / سائنسی ہدایات','Template "%s" already exists.'=>'سانچہ "%s" پہلے سے موجود ہے۔','Template "{expected}" does not exist — create it in the Site Editor first.'=>'ٹیمپلیٹ "{expected}" موجود نہیں — پہلے اسے سائٹ ایڈیٹر میں بنائیں۔','Template has no content.'=>'سانچہ کا مواد نہیں ہے۔','Template mode'=>'ٹیمپلیٹ موڈ','Template not found or not stored in the database.'=>'سانچہ نہیں ملا یا ڈیٹا بیس میں محفوظ نہیں۔','Template part "%s" already exists.'=>'سانچہ حصہ "%s" پہلے سے موجود ہے۔','Template part has no content.'=>'سانچہ کا حصہ کا مواد نہیں ہے۔','Template part not found or not stored in the database.'=>'سانچہ کا حصہ نہیں ملا یا ڈیٹا بیس میں محفوظ نہیں۔','Template Parts'=>'ٹیمپلیٹ پارٹس','Templates'=>'ٹیمپلیٹس','Test connection'=>'کنکشن کا ٹیسٹ کریں','Testing…'=>'آزمائش جاری ہے…','Text domain / locale'=>'ٹیکسٹ ڈومین / لوکیل','Text to translate'=>'ترجمہ کے لیے متن','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'API جواب کیش ہر AI درخواست کا خام نتیجہ اسٹور کرتا ہے — ترجمہ، میٹا تفصیل، اقتباس، اور مواد پیداوار — ان پٹ کا ہیش کے ذریعے کی جاتی ہے (مواد، زبان کا جوڑا، فراہم کنندہ، ماڈل)۔ ایک جیسی ان پٹ کے ساتھ بعد کی درخواستیں کیش سے فراہم کی جاتی ہیں بغیر API کال کے۔ یہ کیش ترجمہ یادداشت سے مختلف ہے: ترجمہ یادداشت بلاک سطح پر کام کرتی ہے اور پوسٹس کے درمیان مشترک ہے؛ API جواب کیش فیچر سطح پر کام کرتا ہے اور ہر پوسٹ کے لیے کیڈ ہے۔','The editor did not accept the content — please try again.'=>'مدیر نے مواد کو قبول نہیں کیا — براہ کرم دوبارہ کوشش کریں۔','The following directive is active in your virtual robots.txt:'=>'آپ کے ورچوئل robots.txt میں درج ذیل ہدایت فعال ہے:','The lf-social-share mu-plugin is active.'=>'lf-social-share mu-پلاگ ان فعال ہے۔','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'lf-social-share mu-پلاگ ان فعال ہے۔ لینگوآ فورج کا بلٹ ان سوشل شیئر غیر فعال ہے — یہ mu-پلاگ URL ری رائٹنگ اور JS ایکشنز کو سنبھالتا ہے۔','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'ہلکی سطح تیز ماڈل استعمال کرتی ہے جو اوپر دی گئی ماڈلز ٹیبل میں ترتیب دیا گیا ہے (پہلا: ہائیکو / فلیش)۔ اگر آپ کو اسنپٹ کے لیے مکمل صفحہ کے مترادف ترجمہ کی درستگی چاہیے تو معیار پر سوئچ کریں۔','The phrase as it appears in the source text.'=>'ماخذ متن میں جیسا ظاہر ہوتا ہے۔','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'پہلی زبان ہمیشہ آپ کی سائٹ کے روٹ پر سروس کی جاتی ہے — راستہ موڈ میں URL پیشگی نہیں، سب ڈومین موڈ میں زبان کا سب ڈومین نہیں۔ دیگر زبانیں یا تو /lang/ راستہ پیشگی استعمال کرتی ہیں (مثلاً example.com/de/) یا زبان کا سب ڈومین (مثلاً de.example.com)، جو نیچے دی گئی URL ساخت کی ترتیب پر منحصر ہے۔','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'SEO → Compatibility ٹیب لائیو ڈیٹیکشن کی حالت دکھاتا ہے اور ہر فیچر کے لیے LF کیا کر رہا ہے اس کی وضاحت کرتا ہے۔','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'شیئر URL ہمیشہ موجودہ صفحہ کی عکاسی کرتا ہے — کوئی دستی URL داخل کرنے کی ضرورت نہیں۔ لینگوآ فورج_social_share_url فلٹر آپ کو کسی بھی سروس کے لیے حل شدہ URL کو اوور رائیڈ کرنے کی اجازت دیتا ہے۔','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'سائٹ میپ خود بخود robots.txt میں اعلان کیا جاتا ہے۔ تمام بڑے سرچ انجن — گوگل، بنگ، یاندیکس — اسے robots.txt سے دریافت کرتے ہیں۔ کوئی دستی جمع کرانے کی ضرورت نہیں۔','The source page has no footnotes.'=>'ماخذ صفحہ میں کوئی نوٹ نہیں ہے۔','The upload failed — please try again.'=>'اپ لوڈ ناکام رہا — براہ کرم دوبارہ کوشش کریں۔','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'ورڈپریس کا بنیادی سائٹ میپ آپ کے تمام مواد کے URLs کی فہرست دیتا ہے۔ LF سائٹ میپ سرچ انجنز کو بتاتا ہے کہ زبان کے ورژن ایک دوسرے سے کس طرح جڑے ہوئے ہیں، XHTML:link hreflang متبادل کے ذریعے۔ دونوں کو گوگل سرچ کنسول میں جمع کروائیں تاکہ مکمل کوریج حاصل ہو۔','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'یہ نوٹس ماخذ صفحہ سے آتے ہیں اور صرف حوالہ کے لیے یہاں دکھائے جاتے ہیں۔ انہیں اس صفحہ میں شامل کریں۔','This is the source page. Footnotes are edited directly in the block editor.'=>'یہ ماخذ صفحہ ہے۔ نوٹ براہ راست بلاک ایڈیٹر میں ترمیم کیے جاتے ہیں۔','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'یہ کلید فی الحال ایک سرور %s سے فراہم کی جا رہی ہے اور اسے یہاں سے ہٹایا نہیں جا سکتا۔ اسے اوور رائیڈ کرنے کے لیے اوپر ایک نئی کلید درج کریں۔','This language is protected and cannot be uninstalled.'=>'یہ زبان محفوظ ہے اور ان انسٹال نہیں کی جا سکتی۔','This language matches the WordPress instance locale and cannot be uninstalled.'=>'یہ زبان ورڈپریس کے لوکل ایبل سے ملتی ہے اور ان انسٹال نہیں کی جا سکتی۔','Tip: to reset a model to the built-in default, clear the field and save.'=>'اشارہ: ایک ماڈل کو بلٹ ان ڈیفالٹ پر ری سیٹ کرنے کے لیے، فیلڈ کو صاف کریں اور محفوظ کریں۔','Title'=>'عنوان','Title is %1$d chars — aim for %2$d–%3$d.'=>'عنوان %1$d حروف ہے — %2$d–%3$d کے لیے ہدف۔','Title is %1$d chars — may be truncated in SERPs (aim for %2$d–%3$d).'=>'عنوان %1$d حروف ہے — SERPs میں کاٹا جا سکتا ہے (مقصد %2$d–%3$d ہے)۔','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'ایک کسٹم انکرپشن خفیہ کا استعمال کرنے کے لیے (جو کہ حاصل شدہ wp_salt قیمت کے بجائے ہے)، اسے wp-config.php میں شامل کریں:','Today'=>'آج','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'ٹوکین کا استعمال فیچر، فراہم کنندہ، اور ماڈل کے لحاظ سے جمع کیا جاتا ہے۔ ہر کامیاب AI کال پر ریکارڈ کیا جاتا ہے؛ ٹیسٹ کنکشن پنگس کو خارج کیا جاتا ہے تاکہ وہ کل کو متاثر نہ کریں۔','Tone'=>'لہجہ','tone'=>'لہجہ','Tone:'=>'لہجہ:','Too many AI requests. Please retry in %d seconds.'=>'بہت زیادہ AI درخواستیں۔ براہ کرم %d سیکنڈ میں دوبارہ کوشش کریں۔','Total'=>'کل','Total tokens'=>'کل ٹوکنز','Translate'=>'ترجمہ کریں','Translate / Revise'=>'ترجمہ / نظر ثانی','Translate / Revise block'=>'بلاک کا ترجمہ / نظر ثانی','Translate all'=>'تمام ترجمہ کریں','Translate chunk'=>'ٹکڑا ترجمہ کریں','Translate Content'=>'مواد کا ترجمہ کریں','Translate missing'=>'غائب ترجمہ کریں','Translate page…'=>'صفحہ ترجمہ کریں…','Translated content'=>'مترجم مواد','Translated Names'=>'ترجمہ شدہ نام','Translated title'=>'مترجم عنوان','Translated to:'=>'ترجمہ شدہ:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'ترجمہ کیا گیا۔ سائٹ ایڈیٹر میں جائزہ لیں — اندرونی روابط، نیویگیشن یو آر ایل، اور ٹیمپلیٹ سلگ خودکار طور پر اپ ڈیٹ نہیں ہوتے۔','Translating…'=>'ترجمہ ہو رہا ہے…','Translation'=>'ترجمہ','Translation Caching'=>'ترجمہ کیشنگ','Translation found but permalink could not be generated'=>'ترجمہ ملا لیکن لنک مستقل لنک تیار نہیں کیا جا سکا','Translation Limits'=>'ترجمہ کی حدیں','Translation Limits & Behavior'=>'ترجمہ کی حدیں اور رویہ','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'ترجمہ کی حدیں: کنٹرول کریں کہ کون سے صارف کے کردار AI ترجمہ کو فعال کرسکتے ہیں، اور ایک ماہانہ ٹوکن بجٹ مقرر کریں۔ بجٹ سے تجاوز کرنے پر AI کالز معطل ہوجائیں گی یہاں تک کہ مہینہ ختم ہو جائے۔','Translation Memory'=>'ترجمہ یادداشت','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'ترجمہ یادداشت AI کے نتائج کو مواد کے ہیش، زبان کے جوڑے، فراہم کنندہ، اور ماڈل کے ذریعے کیش کرتی ہے۔ کسی پوسٹ میں ترمیم کرنے سے کیش انٹری منسوخ ہو جاتی ہے تاکہ اگلی ترجمہ کال تازہ نتیجہ حاصل کرے۔','Translation Memory cleared. %d cached block was removed.'=>'ترجمہ یادداشت صاف کی گئی۔ %d کیش شدہ بلاک ہٹا دیا گیا۔' . "\0" . 'ترجمہ یادداشت صاف کی گئی۔ %d کیش شدہ بلاک ہٹا دیے گئے۔','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'ترجمہ یادداشت: ہر مواد کے ہیش کے مطابق مکمل ترجمہ شدہ پوسٹ کو محفوظ کرتی ہے۔ اسے صاف کریں جب آپ چاہتے ہیں کہ تمام پوسٹس کا دوبارہ ترجمہ زبردستی کیا جائے، چاہے ان کا مواد تبدیل ہوا ہو یا نہ ہوا ہو۔','Translation workflow'=>'ترجمہ کا ورک فلو','Translation, Content Generator'=>'ترجمہ، مواد تخلیق','Treat H2 as H1 equivalent'=>'H2 کو H1 کے مساوی سمجھیں','Type'=>'قسم','Uli Hake'=>'Uli Hake','Uninstall %s'=>'ان انسٹال کریں %s','Uninstall Behaviour'=>'رویے ان انسٹال کریں','Uninstall setting saved.'=>'ان انسٹال سیٹنگ محفوظ کی گئی۔','unknown error'=>'نامعلوم غلطی','Unknown provider.'=>'نامعلوم فراہم کنندہ۔','Unknown search engine.'=>'نامعلوم سرچ انجن۔','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'Hreflang کے برعکس — جہاں LF ہمیشہ دیگر پلگ انز کو اوور رائیڈ کرتا ہے کیونکہ وہ آپ کی کثیر زبان ترتیب کو نہیں جان سکتے — اوپن گراف مختلف ہے: یواست، رینک میتھ، اور ملتے جلتے پلگ انز پہلے سے ہی آپ کے مواد کے لیے صحیح OG ٹیگز پیدا کرتے ہیں۔ ان کی نقل کرنا کوئی فائدہ نہیں دیتا۔ خودکار موڈ میں، LF فعال SEO پلگ انز کا پتہ لگاتا ہے اور صرف وہی شامل کرتا ہے جو وہ فراہم نہیں کر سکتے: og:locale (موجودہ زبان) اور og:locale:alternate (تمام دیگر ترتیب دی گئی زبانیں)۔','Up'=>'اوپر','Upload .mo file'=>'.mo فائل اپ لوڈ کریں','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'تیسری پارٹی پلگ ان کے اسٹرنگز کو اوور رائڈ کرنے کے لیے مرتب شدہ .mo فائلیں اپ لوڈ کریں — مثال کے طور پر، ایک کسٹم ویک بُکنگ ترجمہ جو "کمرہ" کے بجائے "اپارٹمنٹ" استعمال کرتا ہے۔ فائلیں ورڈپریس کے نام کی قاعدہ کی پیروی کرتی ہیں: {textdomain}-{locale}.mo (مثلاً vikbooking-ca.mo)۔ یہ اپ لوڈز فولڈر میں محفوظ ہوتی ہیں اور پلگ ان اپ ڈیٹس کے دوران برقرار رہتی ہیں۔','Upload Override'=>'اوور رائڈ اپ لوڈ کریں','URL could not be mapped to a post — check the link target exists'=>'URL کو پوسٹ سے منسلک نہیں کیا جا سکا — چیک کریں کہ لنک کا ہدف موجود ہے','URL structure'=>'URL ساخت','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL کا ڈھانچہ: پاتھ-پری فکس موڈ (مثلاً.com/de/) کسی سرور تبدیلی کے بغیر کام کرتا ہے۔ سب ڈومین موڈ (de.example.com) کے لیے ایک وائلڈ کارڈ DNS ریکارڈ، وائلڈ کارڈ SSL سرٹیفکیٹ، اور ویب سرور کنفیگریشن میں تبدیلی کی ضرورت ہوتی ہے — سرور سیٹ اپ گائیڈ دیکھیں۔','URL to enter'=>'داخل کرنے کے لیے URL','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'جب دستیاب ہو تو مقامی شیئر استعمال کریں؛ کلپ بورڈ کاپی پر واپس جائیں۔ "شیئر" بٹنز کے لیے تجویز کردہ ڈیفالٹ۔','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'اس صفحہ کے اوپر ٹیبز کا استعمال کریں تاکہ ہر علاقے کو ترتیب دیا جا سکے۔ روٹر ٹیب میں تبدیلیاں فوری اثر انداز ہوتی ہیں؛ AI کیز اور ماڈل سیٹنگز میں تبدیلیاں اگلی AI درخواست پر لاگو ہوتی ہیں۔','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'زبان کے جوڑے کے مطابق صارف کے زیر انتظام اصطلاحات کی جدول۔ اندراجات ترجمہ نظام کے اشارے میں شامل کی جاتی ہیں تاکہ AI ترجیحی اصطلاحات کو مستقل استعمال کرے — شعبہ جاتی الفاظ ("kWp", "PPA", "interconnection point")، برانڈ کے نام جو ترجمہ نہیں ہونے چاہئیں، اور معیاری ضابطہ بندی کے جملے کے لیے اہم۔ دونوں زبان کے فیلڈز اختیاری ہیں: "ماخذ زبان" کو خالی چھوڑیں تاکہ یہ اندراج کسی بھی زبان سے ترجمہ کرنے کے باوجود لاگو ہو؛ "ہدف زبان" کو خالی چھوڑیں تاکہ یہ تمام ہدف زبانوں پر ایک ساتھ لاگو ہو۔','Using custom meta description.'=>'کاستم میٹا تفصیل استعمال کر رہے ہیں۔','Using LF AI meta description.'=>'LF AI میٹا تفصیل استعمال کر رہا ہے۔','Value source'=>'ویلیو سورس','View'=>'دیکھیں','View built-in default'=>'بلٹ ان ڈیفالٹ دیکھیں','View current robots.txt'=>'موجودہ robots.txt دیکھیں','View details'=>'تفصیلات دیکھیں','View Lingua Forge details'=>'لینگوا فورج کی تفصیلات دیکھیں','Visit plugin site'=>'پلگ ان کی سائٹ پر جائیں','Warning:'=>'خبردار:','WebSite'=>'ویب سائٹ','WebSite — front page / blog index'=>'ویب سائٹ — فرنٹ پیج / بلاگ انڈیکس','What LF provides — and collision avoidance'=>'جو LF فراہم کرتا ہے — اور تصادم سے بچاؤ','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'جو LF فراہم کرتا ہے: ہر ترتیب دی گئی زبان کے لیے hreflang ٹیگز، Open Graph اور Twitter Card ٹیگز کے ساتھ og:locale اور og:locale:alternate، Schema.org JSON-LD کے ساتھ inLanguage تشریحات، اور /lf-sitemap.xml پر ایک مخصوص کثیر زبان سائٹ میپ جس میں تمام ترجمہ گروپ کے لیے XHTML:link متبادل اندراجات شامل ہیں۔','When another SEO plugin is installed'=>'جب کوئی دوسرا SEO پلگ ان انسٹال ہو','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'جب ڈیبگ لاگنگ فعال ہوتی ہے (نیچے ٹوگل کے ذریعے یا wp-config.php میں LINGUAFORGE_AI_DEBUG کو ڈیفائن کرکے)، ترجمہ اور ایف ایس ای ٹیمپلیٹ ترجمہ خصوصیات اپنی خام اے آئی پرامپٹس اور جوابات کو دشواری حل کے لیے ڈسک پر لکھتی ہیں۔ اس سیکشن کا استعمال اس آؤٹ پٹ کی نگرانی کے لیے کریں اور اسے صاف کریں جب آپ کو ضرورت ہو — فائلیں بڑے صفحات پر تیزی سے بڑھ سکتی ہیں۔ ہدف ڈائریکٹری کو linguaforge_debug_dir فلٹر کے ذریعے ترتیب دیں۔','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'جب فعال ہو، تو پہلی بار آنے والے زائرین جن کے پاس زبان کا کوکی نہیں اور URL میں زبان کا پیش لفظ نہیں، سب سے قریب ملنے والی زبان کے ورژن پر ری ڈائریکٹ کیے جاتے ہیں۔ اگر براؤزر کی ترجیحی زبان فعال روٹر زبانوں میں شامل نہیں ہے، تو ری ڈائریکٹ کو چھوڑ دیا جاتا ہے۔ جب کوئی زائرین سوئچر کے ذریعے زبان منتخب کرتا ہے، تو کوکی ترجیح حاصل کرتی ہے اور براؤزر ہیڈر کو مستقبل کے دوروں پر نظر انداز کیا جاتا ہے۔','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'جب فعال ہو، لینگوآ فورج پروڈکٹ صفحات پر درج ذیل اضافی میٹا ٹیگز پیدا کرتا ہے: og:type=product، og:price:amount، og:price:currency، og:availability، اور ان کے product: namespace کے متبادل جو فیس بک کیٹلاگ استعمال کرتا ہے۔','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'جب فعال ہو، سائٹ میپ URL خود بخود robots.txt میں اعلان کیا جاتا ہے اور ترجمہ شدہ مواد محفوظ ہونے پر کیش کو تازہ کیا جاتا ہے۔','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'جب Yoast SEO، Rank Math، All in One SEO، یا SEOPress فعال ہو، لینگوآ فورج خودکار طور پر ان کے hreflang آؤٹ پٹ کو فلٹر کے ذریعے روکتا ہے۔ عمومی SEO پلگ انز ایک زبان کے URL ڈھانچے پر مبنی hreflang پیدا کرتے ہیں اور آپ کی کثیر زبان روٹنگ ترتیب کو مدنظر نہیں رکھتے؛ LF کا آؤٹ پٹ ہمیشہ درست ہوتا ہے۔','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'مکمل صفحہ ترجمہ کے لیے کون سا ماڈل استعمال کرنا ہے۔ معیار اوپر دی گئی ماڈلز ٹیبل میں ترتیب دیا گیا ماڈل استعمال کرتا ہے اور درست، طویل شکل کے ترجمہ کے لیے تجویز کیا جاتا ہے۔ صرف رفتار یا لاگت کو ترجیح دینے اور مواد مختصر ہونے کی صورت میں Light پر سوئچ کریں۔','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'جب فعال ہو، mu-پلاگ ان بنیادی OG سیٹ کو سنبھالتا ہے اور LF صرف لوکل ٹیگز پیدا کرتا ہے (خودکار موڈ)۔ اسے ہٹانے سے LF مکمل OG موڈ میں چلا جاتا ہے۔','WooCommerce'=>'وو کامرس','WooCommerce product price'=>'وو کامرس پروڈکٹ قیمت','WooCommerce SEO settings saved.'=>'وو کامرس SEO سیٹنگز محفوظ ہوگئیں۔','WooCommerce store currency'=>'وو کامرس اسٹور کرنسی','Word count'=>'الفاظ کی تعداد','WP core canonical active (hreflang disabled)'=>'WP کور کینونیکل فعال (hreflang غیر فعال)','WP-CLI reference'=>'WP-CLI حوالہ','Write AI prompts and responses to disk for troubleshooting'=>'مسئلے حل کے لیے اے آئی پرامپٹس اور جوابات کو ڈسک پر لکھیں','XML Sitemap'=>'ایکس ایم ایل سائٹ میپ','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'آپ کلیدوں کو مستقل یا ماحولیاتی متغیر کے طور پر بھی تعریف کر سکتے ہیں (مثلاً wp-config.php میں)۔ یہ ذرائع خودکار طور پر استعمال ہوتے ہیں جب کوئی ڈیٹا بیس کلید محفوظ نہیں ہوتی۔','You do not have permission to manage these settings.'=>'آپ کو ان سیٹنگز کو منظم کرنے کی اجازت نہیں ہے۔','You do not have permission to read this post.'=>'آپ کو اس پوسٹ کو پڑھنے کی اجازت نہیں ہے۔','{n} stale path(s)'=>'{n} پرانی راہ/راہیں','~%d min read'=>'~%d منٹ پڑھیں' . "\0" . '~%d منٹ پڑھیں','— Any source language —'=>'— کوئی بھی ماخذ زبان —','— Any target language —'=>'— کوئی بھی ہدف زبان —','— Any target —'=>'— کوئی بھی ہدف —','— Any —'=>'— کوئی بھی —','— auto-detect —'=>'— خودکار شناخت —','— Deferred to plugin'=>'— پلگ ان کے حوالے کیا گیا','— Disabled'=>'— غیر فعال','— Not detected'=>'— نہیں معلوم','— select a language —'=>'— ایک زبان منتخب کریں —','— toggle in Settings → Behavior.'=>'— سیٹنگز → رویہ میں ٹوگل۔','← Back'=>'← واپس','↑ Detected from current post'=>'↑ موجودہ پوسٹ سے معلوم ہوا','→ Locale tags only (manual setting)'=>'→ صرف لوکل ٹیگز (دستی سیٹنگ)','→ Locale tags only — deferring base OG to plugin'=>'→ صرف لوکل ٹیگز — بنیادی OG کو پلگ ان پر ملتوی کرنا','↺ Re-translate'=>'↺ دوبارہ ترجمہ','↺ Refine'=>'↺ بہتر بنائیں','↺ Refresh'=>'↺ تازہ کریں','↺ Refresh AI Analysis'=>'↺ AI تجزیہ کو تازہ کریں','↺ Refreshing…'=>'↺ تازہ کاری ہو رہی ہے…','⚠ Borderline'=>'⚠ حد سے زیادہ قریب','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ کوئی <strong>{lang}</strong> پوسٹس نہیں ملی۔ یقینی بنائیں کہ تمام ترجمہ شدہ پوسٹس میں زبان کا میٹا <strong>{lang}</strong> پر سیٹ ہے۔','⚠ No changes'=>'⚠ کوئی تبدیلی نہیں','⚠ No changes — re-scan?'=>'⚠ کوئی تبدیلی نہیں — دوبارہ اسکین کریں؟','✅ Fixed ({n})'=>'✅ ٹھیک کیا ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ <strong>{lang}</strong> کے لیے کوئی ٹوٹے ہوئے لنکس یا ٹیمپلیٹ میں غلطیاں نہیں پائی گئیں۔ <strong>{scanned}</strong> پوسٹ/صفحات اسکین کی گئیں — تمام چیک پاس ہو گئے۔ ٹیمپلیٹ پارٹس کے لنکس (ہیڈر، فوٹر، سائیڈبار) یہاں شامل نہیں ہیں — ان کو علیحدہ سے چیک کرنے کے لیے فکس ٹیمپلیٹ پارٹس بٹن استعمال کریں۔','✅ Template fixed'=>'✅ ٹیمپلیٹ درست ہو گیا','✓ %s notified successfully.'=>'✓ %s کامیابی سے اطلاع دی گئی۔','✓ Active'=>'✓ فعال','✓ Active at /lf-sitemap.xml'=>'✓ /lf-sitemap.xml پر فعال','✓ Active — %d URL entry with language alternates'=>'✓ فعال — %d URL داخلہ زبان کے متبادل کے ساتھ' . "\0" . '✓ فعال — %d URL داخلہ زبان کے متبادل کے ساتھ','✓ Active — full OG + Twitter Cards'=>'✓ فعال — مکمل OG + ٹویٹر کارڈز','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ فعال — صرف لوکل ٹیگز (og:locale، og:locale:alternate)','✓ All parts created.'=>'✓ تمام حصے بن گئے۔','✓ All templates created.'=>'✓ تمام ٹیمپلیٹس بن گئے۔','✓ All translated.'=>'✓ سب ترجمہ ہو گیا۔','✓ Configured'=>'✓ ترتیب دیا گیا','✓ Connection OK'=>'✓ کنکشن ٹھیک ہے','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ مواد تیار — جائزہ لینے، بہتر بنانے، اور لاگو کرنے کے لیے اوورلے دیکھیں۔','✓ Done'=>'✓ مکمل','✓ Enabled'=>'✓ فعال','✓ Good length'=>'✓ اچھا طول','✓ Hreflang active'=>'✓ ہریف لینگ فعال','✓ In safe storage'=>'✓ محفوظ اسٹوریج میں','✓ Language installed.'=>'✓ زبان انسٹال ہو گئی ہے۔','✓ LF outputs'=>'✓ LF آؤٹ پٹس','✓ LF outputs Article / WebPage / WebSite'=>'✓ LF آؤٹ پٹس آرٹیکل / ویب پیج / ویب سائٹ','✓ LF outputs full OG + Twitter Cards'=>'✓ فعال — مکمل OG + ٹویٹر کارڈز','✓ LF outputs — plugin hreflang suppressed'=>'✓ LF آؤٹ پٹس — پلگ ان ہریف لینگ کو دبایا گیا','✓ Links fixed.'=>'✓ روابط درست ہو گئے۔','✓ Nav refs fixed.'=>'✓ نیویگیشن ریفرنسز درست۔','✓ Parts fixed.'=>'✓ حصے درست ہو گئے۔','✓ Pattern translated.'=>'✓ پیٹرن ترجمہ ہو گیا۔','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ فزیکل robots.txt ملا۔ LF کا سائٹ میپ ہدایت نامہ موجود ہے۔','✓ Refined — review the updated draft above.'=>'✓ ترمیم شدہ — اوپر دی گئی مسودہ کا جائزہ لیں۔','✓ Translation saved'=>'✓ ترجمہ محفوظ ہو گیا','✓ WP core canonical removed'=>'✓ WP کور کینونیکل ہٹا دیا گیا','✗ %s ping failed. The sitemap URL is still announced in robots.txt — the search engine will discover it on its next crawl.'=>'✗ %s پنگ ناکام۔ سائٹ میپ URL اب بھی robots.txt میں اعلان کیا گیا ہے — سرچ انجن اسے اپنی اگلی کرال پر دریافت کرے گا۔','✗ Disabled'=>'✗ غیر فعال','✗ Error:'=>'✗ خرابی:','✗ Failed:'=>'✗ ناکام:','✗ Not configured'=>'✗ ترتیب نہیں دیا گیا','✗ Too long'=>'✗ بہت لمبا','✗ Too short'=>'✗ بہت چھوٹا','❌ Failed'=>'❌ ناکام','📄 Wrong template'=>'📄 غلط ٹیمپلیٹ','📍 Stale path (page moved)'=>'📍 پرانی راہ (صفحہ منتقل ہو گیا)']];
